window.WB_BOOK=window.WB_BOOK||{};window.WB_BOOK["week15"]={"id":"week15","n":16,"section":"X","label":"Paper 01 Drill","title":"Paper 01 MCQ Drill (Sections A–E) & Paper 032 Practical Skills","titleText":"Paper 01 MCQ Drill (Sections A–E) & Paper 032 Practical Skills","subtitle":"Rapid revision of every section, 90 practice multiple-choice items, exam technique, and the practical skills for Paper 032","intro":"This is an **exam-preparation** book, not a new topic. Paper 02 is on **Tuesday 5 January 2027** and Paper 01 (multiple choice) is on **Monday 25 January 2027**. Paper 01 has **60 questions in 1 hour 15 minutes**, so you have about **75 seconds per question**. Every section, A to E, is tested. Units 15.1–15.5 give you a one-page rapid-revision table for each section and 12 practice questions. Unit 15.6 teaches you HOW to answer multiple-choice questions fast and accurately. Unit 15.7 is for Paper 032 (the practical paper) and is only needed if you are entered as an alternate (private) candidate. Finish with the 30-question mixed test, timed.","objectives":[{"code":"A","text":"Section A Mechanics: measurement, vectors, forces, moments, motion, momentum, energy, power and pressure"},{"code":"B","text":"Section B Thermal physics and kinetic theory: temperature, thermometers, gas laws, specific heat and latent heat, heat transfer"},{"code":"C","text":"Section C Waves and optics: wave equation, sound, EM spectrum, reflection, refraction, total internal reflection and lenses"},{"code":"D","text":"Section D Electricity and magnetism: static, current, circuits, mains, electronics, magnetism, motor effect, induction and transformers"},{"code":"E","text":"Section E The physics of the atom: atomic models, structure, radioactivity, half-life, nuclear equations and uses"},{"code":"P01","text":"Paper 01 technique: answer 60 MCQs in 75 minutes using elimination, unit checks, estimating and fast graph reading"},{"code":"P032","text":"Paper 032 practical skills (alternate candidates only): reading instruments, tables, graphs, precautions, errors and planning"}],"formulaCard":[{"tex":"\\rho =m\\div V","meaning":"density = mass ÷ volume","units":"⟪\\mathrm{kg}\\,\\mathrm{m}^{-3}\\ (1\\,\\mathrm{g}\\,\\mathrm{cm}^{-3}=1000\\,\\mathrm{kg}\\,\\mathrm{m}^{-3})⟫"},{"tex":"W=mg","meaning":"weight; ⟪g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1}⟫","units":"N"},{"tex":"\\text{Moment }=F\\times d","meaning":"d = perpendicular distance to pivot","units":"N m"},{"tex":"F=kx","meaning":"Hooke's law; x = extension","units":"N; k in N m^−1^"},{"tex":"a=(v-u)\\div t","meaning":"acceleration; = gradient of v–t graph","units":"m s^−2^"},{"tex":"F=ma","meaning":"F = resultant force","units":"N"},{"tex":"p=mv","meaning":"momentum; conserved in collisions","units":"kg m s^−1^"},{"tex":"W=Fd;\\quad E_{p}=mgh;\\quad E_{k}=\\tfrac{1}{2}mv^{2}","meaning":"work done; potential energy; kinetic energy","units":"J"},{"tex":"P=E\\div t","meaning":"power","units":"W"},{"tex":"\\text{Efficiency }=\\text{ useful out }\\div \\text{ total in }\\times 100\\%","meaning":"always < 100%","units":"%"},{"tex":"P=F\\div A;\\quad P=\\rho gh","meaning":"pressure; pressure in a fluid","units":"Pa"},{"tex":"T/K=\\theta /{}^{\\circ}\\mathrm{C}+273","meaning":"kelvin conversion","units":"K"},{"tex":"p_{1}V_{1}\\div T_{1}=p_{2}V_{2}\\div T_{2}","meaning":"general gas law (T in kelvin)","units":""},{"tex":"E=mc\\Delta \\theta ;\\quad E=ml","meaning":"specific heat capacity; specific latent heat","units":"J kg^−1^ K^−1^; J kg^−1^"},{"tex":"v=f\\lambda ;\\quad T=1\\div f","meaning":"wave equation; period","units":"m s^−1^; s"},{"tex":"\\text{echo: }d=vt\\div 2","meaning":"sound goes there and back","units":"m"},{"tex":"n=\\sin i\\div \\sin r=c\\div v","meaning":"refractive index","units":"no unit"},{"tex":"\\sin c=1\\div n","meaning":"critical angle","units":""},{"tex":"1\\div f=1\\div u+1\\div v;\\quad m=v\\div u","meaning":"lens formula; magnification","units":""},{"tex":"Q=\\text{ It};\\quad V=E\\div Q","meaning":"charge; potential difference","units":"C; V"},{"tex":"V=IR;\\quad P=IV=I^{2}R;\\quad E=Pt","meaning":"Ohm's law; power; energy","units":"Ω; W; J or kWh"},{"tex":"R=R_{1}+R_{2};\\quad 1\\div R=1\\div R_{1}+1\\div R_{2}","meaning":"series; parallel","units":"Ω"},{"tex":"V_{p}\\div V_{s}=N_{p}\\div N_{s};\\quad V_{p}I_{p}=V_{s}I_{s}","meaning":"ideal transformer","units":""},{"tex":"A=Z+N","meaning":"nucleon number = protons + neutrons","units":""},{"tex":"\\alpha {:}\\ A-4,\\ Z-2;\\quad \\beta {:}\\ A\\text{ same, }Z+1;\\quad \\gamma {:}\\ \\text{ no change}","meaning":"nuclear equations","units":""},{"tex":"\\text{fraction left }=(\\tfrac{1}{2})^{n}","meaning":"n = number of half-lives","units":""},{"tex":"E=mc^{2}","meaning":"mass defect → energy; ⟪c=3.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","units":"J"}],"glossary":[{"term":"Stem","def":"The question part of a multiple-choice item."},{"term":"Key","def":"The correct option in a multiple-choice item."},{"term":"Distractor","def":"A wrong option, usually the answer you get from a common mistake."},{"term":"Elimination","def":"Crossing out options you know are wrong before choosing."},{"term":"Alternate candidate","def":"A private candidate who sits Paper 032 instead of doing the SBA."},{"term":"Accuracy","def":"How close a measurement is to the true value."},{"term":"Precision","def":"How close repeated readings are to each other; also the smallest division read."},{"term":"Sensitivity","def":"How much an instrument's reading changes for a small change in the quantity."},{"term":"Range","def":"The lowest to highest values an instrument can measure."},{"term":"Parallax error","def":"Error from reading a scale with the eye not directly in line with the mark."},{"term":"Zero error","def":"An instrument shows a reading when it should read zero; a systematic error."},{"term":"Random error","def":"Error that varies unpredictably; reduced by repeating and averaging."},{"term":"Systematic error","def":"Error that is the same every time (e.g. zero error); not removed by averaging."},{"term":"Fiducial mark","def":"A fixed reference mark (e.g. at the centre of a pendulum swing) used for counting oscillations."},{"term":"Manipulated variable","def":"The variable you deliberately change (independent variable)."},{"term":"Responding variable","def":"The variable you measure (dependent variable)."},{"term":"Controlled variable","def":"A variable kept the same so the test is fair."},{"term":"Hypothesis","def":"A testable statement predicting how one variable affects another."}],"studyPlan":[["Day 1","Units 15.1 and 15.2: read the revision tables, then do the 24 practice items (timed: 30 min)","45 min",""],["Day 2","Units 15.3 and 15.4: revision tables + 24 practice items (timed: 30 min)","45 min",""],["Day 3","Unit 15.5 + Unit 15.6 (MCQ technique); redo every item you got wrong","45 min",""],["Day 4","30-question mixed test, STRICTLY timed (38 min); mark it; fill in the Mistake Log","45 min",""],["Day 5 (032 only)","Unit 15.7 practical skills + Past-Paper Practice PP1 and PP2","30 min",""],["Every day","Formula & Fact Card: cover the left column and test yourself","10 min",""]],"lessons":[{"id":"week15.15.1","kind":"unit","unit":"15.1","title":"Section A Mechanics: Rapid Revision","titleText":"Section A Mechanics: Rapid Revision","goals":[{"code":"A","text":"Section A Mechanics: measurement, vectors, forces, moments, motion, momentum, energy, power and pressure"}],"codes":["A"],"words":[{"term":"Key","def":"The correct option in a multiple-choice item."},{"term":"Distractor","def":"A wrong option, usually the answer you get from a common mistake."},{"term":"Zero error","def":"An instrument shows a reading when it should read zero; a systematic error."},{"term":"Systematic error","def":"Error that is the same every time (e.g. zero error); not removed by averaging."}],"learn":{"notes":[{"type":"p","text":"Section A is the biggest section of the syllabus, so it gives the most Paper 01 items. Learn every row of this table."},{"type":"table","headers":["Topic","Key fact / formula","Unit or trap"],"rows":[["Galileo","Used experiments (inclined planes, pendulums); challenged Aristotle","Heavy and light objects fall with the same acceleration (no air)"],["Pendulum","Period T depends ONLY on length l (small swings); ⟪T^{2}\\propto l⟫","Not on mass or amplitude. Time 20 swings, divide by 20"],["Errors","Random: scatter, reduce by repeating and averaging. Systematic: same every time (zero error)","Averaging does NOT remove a systematic error"],["Instruments","Metre rule 1 mm; vernier 0.1 mm; micrometer 0.01 mm; stopwatch 0.01 s","Human reaction time ≈ 0.2 s"],["Density","⟪\\rho =m\\div V⟫","kg m^−3^; ⟪1\\,\\mathrm{g}\\,\\mathrm{cm}^{-3}=1000\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫"],["Vectors","Have size AND direction: force, velocity, displacement, acceleration, momentum","Scalars: mass, speed, distance, energy, time"],["Resultant","Same direction: add. Opposite: subtract. At 90°: ⟪R=\\sqrt{a^{2}+b^{2}}⟫","6 N and 8 N at 90° → 10 N"],["Weight","⟪W=mg⟫, ⟪g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1}⟫","Mass in kg, weight in N"],["Moments","Moment ⟪=F⟫ × perpendicular distance; balance: clockwise = anticlockwise","N m (distance to the PIVOT)"],["Stability","Low centre of gravity + wide base = stable","Topples when line of weight falls outside base"],["Hooke's law","⟪F=kx⟫ (up to the limit of proportionality)","x = EXTENSION, not total length"],["Motion graphs","s–t gradient = velocity; v–t gradient = acceleration; area under v–t = distance","⟪a=(v-u)\\div t⟫, m s^−2^"],["Newton","1st: no resultant force, no change in motion. 2nd: ⟪F=ma⟫. 3rd: equal and opposite pairs on DIFFERENT bodies","F is the RESULTANT force"],["Momentum","⟪p=mv⟫; total momentum before = total after (no external force)","kg m s^−1^"],["Energy","⟪W=Fd⟫; ⟪E_{p}=mgh⟫; ⟪E_{k}=\\tfrac{1}{2}mv^{2}⟫; ⟪P=E\\div t⟫","J; ⟪W=\\mathrm{J}\\,\\mathrm{s}^{-1}⟫"],["Efficiency","useful output ÷ total input × 100%","Always less than 100%"],["Pressure","⟪P=F\\div A⟫; in a fluid ⟪P=\\rho gh⟫","⟪\\mathrm{Pa}=\\mathrm{N}\\,\\mathrm{m}^{-2}⟫"],["Floating","Upthrust = weight of fluid displaced (Archimedes). Floats when upthrust = weight","Denser than fluid → sinks"],["Derived units","⟪\\mathrm{N}=\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫; ⟪\\mathrm{J}=\\mathrm{kg}\\,\\mathrm{m}^{2}\\,\\mathrm{s}^{-2}⟫; ⟪\\mathrm{W}=\\mathrm{kg}\\,\\mathrm{m}^{2}\\,\\mathrm{s}^{-3}⟫; ⟪\\mathrm{Pa}=\\mathrm{kg}\\,\\mathrm{m}^{-1}\\,\\mathrm{s}^{-2}⟫","Build from the formula"]]}],"examples":[{"id":"week15.15.1.e1","title":"Power (a typical calculation item)","question":"A girl lifts a 2.0 kg bag through a height of 3.0 m in 4.0 s. What is her useful power? (A) 1.5 W (B) 6.0 W (C) 15 W (D) 60 W","steps":[{"label":"Formula","text":"⟪P=E\\div t⟫, and ⟪E=mgh⟫"},{"label":"Substitute","text":"⟪E=2.0\\times 10\\times 3.0=60\\,\\mathrm{J}⟫; ⟪P=60\\div 4.0⟫"},{"label":"Answer","text":"⟪P=15\\,\\mathrm{W}⟫"},{"label":"Distractor check","text":"60 W (D) is the trap: that is the ENERGY in joules, not the power."}],"answer":"C (15 W)"},{"id":"week15.15.1.e2","title":"Density unit change","question":"A block of mass 200 g has a volume of 80 cm^3^. What is its density in kg m^−3^?","steps":[{"label":"Formula","text":"⟪\\rho =m\\div V⟫"},{"label":"Substitute","text":"⟪\\rho =200\\div 80=2.5\\,\\mathrm{g}\\,\\mathrm{cm}^{-3}⟫"},{"label":"Convert","text":"× 1000 → 2500 kg m^−3^"}],"answer":"⟪2500\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}\\ (2.5\\times 10^{3}\\,\\mathrm{kg}\\,\\mathrm{m}^{-3})⟫"}]},"tryit":[{"id":"week15.15.1.p1","kind":"mcq","q":"Which of the following is a vector quantity?","marks":1,"level":1,"options":["mass","speed","momentum","energy"],"answer":"C","explanation":"(1). Momentum has direction (⟪p=mv⟫, v is a vector). Mass, speed and energy have size only.","section":"try"},{"id":"week15.15.1.p2","kind":"mcq","q":"The unit of pressure, written in base units, is","marks":1,"level":1,"options":["kg m^−1^ s^−2^","kg m s^−2^","kg m^2^ s^−2^","kg m^−2^ s^−1^"],"answer":"A","explanation":"(1). ⟪\\mathrm{Pa}=N\\div m^{2}=\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-2}\\div m^{2}=\\mathrm{kg}\\,\\mathrm{m}^{-1}\\,\\mathrm{s}^{-2}⟫. B is the newton; C is the joule.","section":"try"}],"practice":[{"id":"week15.15.1.p3","kind":"mcq","q":"The period of a simple pendulum (small swings) depends on","marks":1,"level":1,"options":["the mass of the bob","the material of the bob","the number of swings timed","the length of the string"],"answer":"D","explanation":"(1). T depends only on length ⟪(T^{2}\\propto l)⟫. Galileo showed mass does not matter.","section":"practice"},{"id":"week15.15.1.p4","kind":"mcq","q":"Two forces of 6 N (east) and 8 N (north) act on a point. The size of the resultant is","marks":1,"level":1,"options":["2 N","14 N","48 N","10 N"],"answer":"D","explanation":"(1). At 90°: ⟪R=\\sqrt{6^{2}+8^{2}}=\\sqrt{100}=10\\,\\mathrm{N}⟫. 14 N would only be correct if they acted in the same direction.","section":"practice"},{"id":"week15.15.1.p5","kind":"mcq","q":"A uniform metre rule is balanced at its 50 cm mark. A 2.0 N weight hangs at the 20 cm mark. What weight at the 90 cm mark will balance the rule?","marks":1,"level":1,"options":["2.7 N","1.5 N","0.67 N","3.0 N"],"answer":"B","explanation":"(1). Distances from pivot: 30 cm and 40 cm. ⟪2.0\\times 30=W\\times 40⟫, so ⟪W=60\\div 40=1.5\\,\\mathrm{N}⟫. Using the scale readings (20 and 90) instead of distances from the pivot is the trap.","section":"practice"},{"id":"week15.15.1.p6","kind":"mcq","q":"A force of 4.0 N stretches a spring by 2.0 cm. What is the extension when the force is 10 N? (The limit of proportionality is not reached.)","marks":1,"level":1,"options":["5.0 cm","2.5 cm","8.0 cm","20 cm"],"answer":"A","explanation":"(1). ⟪k=4.0\\div 2.0=2.0\\,\\mathrm{N}\\,\\mathrm{cm}^{-1}⟫; ⟪x=10\\div 2.0=5.0\\,\\mathrm{cm}⟫.","section":"practice"},{"id":"week15.15.1.p7","kind":"mcq","q":"The velocity–time graph shows the motion of a car. How far does the car travel in the first 10 s?","marks":1,"level":1,"img":{"src":"img/week15/vt","alt":"The velocity–time graph shows the motion of a car. How far does the car travel in the first 10 s?","w":932,"h":574},"options":["120 m","200 m","160 m","80 m"],"answer":"C","explanation":"(1). Distance = area under graph = triangle ⟪(\\tfrac{1}{2}\\times 4\\times 20=40\\,\\mathrm{m})⟫ + rectangle ⟪(6\\times 20=120\\,\\mathrm{m})=160\\,\\mathrm{m}⟫. 200 m treats the whole 10 s as 20 m s^−1^.","section":"practice"},{"id":"week15.15.1.p8","kind":"mcq","q":"A diver is 3.0 m below the surface of water (density 1000 kg m^−3^). The pressure caused by the water at this depth is","marks":1,"level":1,"options":["⟪3.0\\times 10^{4}\\,\\mathrm{Pa}⟫","⟪3.0\\times 10^{2}\\,\\mathrm{Pa}⟫","⟪3.0\\times 10^{3}\\,\\mathrm{Pa}⟫","⟪3.0\\times 10^{5}\\,\\mathrm{Pa}⟫"],"answer":"A","explanation":"(1). ⟪P=\\rho gh=1000\\times 10\\times 3.0=30\\,000\\,\\mathrm{Pa}=3.0\\times 10^{4}\\,\\mathrm{Pa}⟫. C forgets g.","section":"practice"},{"id":"week15.15.1.p9","kind":"mcq","q":"A horizontal force of 12 N pushes a 3.0 kg box, but friction of 3.0 N opposes it. The acceleration of the box is","marks":1,"level":1,"options":["4.0 m s^−2^","3.0 m s^−2^","5.0 m s^−2^","36 m s^−2^"],"answer":"B","explanation":"(1). Resultant force ⟪=12-3.0=9.0\\,\\mathrm{N}⟫; ⟪a=F\\div m=9.0\\div 3.0=3.0\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫. A (4.0) ignores friction.","section":"practice"},{"id":"week15.15.1.p10","kind":"mcq","q":"A 2.0 kg trolley moving at 3.0 m s^−1^ hits a stationary 1.0 kg trolley. They stick together. Their common speed is","marks":1,"level":1,"options":["1.0 m s^−1^","1.5 m s^−1^","3.0 m s^−1^","2.0 m s^−1^"],"answer":"D","explanation":"(1). Momentum before ⟪=2.0\\times 3.0=6.0\\,\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫; after: ⟪6.0=3.0\\times v⟫, so ⟪v=2.0\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫. Total mass is 3.0 kg, not 2.0 kg.","section":"practice"}],"exit":[{"id":"week15.15.1.p11","kind":"mcq","q":"A ball is dropped from a height of 5.0 m. Ignoring air resistance, its speed just before it hits the ground is","marks":1,"level":1,"options":["5.0 m s^−1^","50 m s^−1^","10 m s^−1^","100 m s^−1^"],"answer":"C","explanation":"(1). ⟪mgh=\\tfrac{1}{2}mv^{2}⟫, so ⟪v=\\sqrt{2gh}=\\sqrt{2\\times 10\\times 5.0}=\\sqrt{100}=10\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫. The mass cancels. 100 is v^2^, not v.","section":"exit"},{"id":"week15.15.1.p12","kind":"mcq","q":"An electric motor receives 800 J of energy and does 600 J of useful work. Its efficiency is","marks":1,"level":1,"options":["133%","75%","25%","60%"],"answer":"B","explanation":"(1). Efficiency ⟪=600\\div 800\\times 100\\%=75\\%⟫. Efficiency can never be more than 100% (A is upside down).","section":"exit"}],"warmup":[{"id":"week15.15.1.w1","kind":"self","q":"How long is Paper 02, how many marks, and how many questions must you answer?","marks":1,"level":1,"scheme":"2 h 30 min; 100 marks; all six questions (Q1 25 marks, Q2–Q6 15 marks each).","points":[{"text":"2 h 30 min; 100 marks; all six questions (Q1 25 marks, Q2–Q6 15 marks each).","marks":1}],"section":"warmup","src":"week13.r1"},{"id":"week15.15.1.w2","kind":"self","q":"What is the difference between \"state\" and \"explain\"?","marks":1,"level":1,"scheme":"State: short fact only. Explain: give the reason using physics (because… so…).","points":[{"text":"State: short fact only. Explain: give the reason using physics (because… so…).","marks":1}],"section":"warmup","src":"week13.r2"},{"id":"week15.15.1.w3","kind":"self","q":"What do the letters SPLAT stand for?","marks":1,"level":1,"scheme":"Scale, Points, Line (of best fit), Axes (labelled with quantity/unit), Title.","points":[{"text":"Scale, Points, Line (of best fit), Axes (labelled with quantity/unit), Title.","marks":1}],"section":"warmup","src":"week13.r3"},{"id":"week15.15.1.w4","kind":"self","q":"What are the three lines of a full-mark calculation?","marks":1,"level":1,"scheme":"Formula; substitution (with SI units); answer with unit (to sensible sig. figs).","points":[{"text":"Formula; substitution (with SI units); answer with unit (to sensible sig. figs).","marks":1}],"section":"warmup","src":"week13.r4"},{"id":"week15.15.1.w5","kind":"self","q":"Name your two biggest error codes from the mock and one fix for each.","marks":1,"level":1,"scheme":"Personal — accept any genuine codes from his tally with a specific fix (e.g. U → convert before substituting).","points":[{"text":"Personal — accept any genuine codes from his tally with a specific fix (e.g. U → convert before substituting).","marks":1}],"section":"warmup","src":"week13.r5"}],"quickStart":[{"type":"p","text":"Know the paper before you sit it. Nothing about the format should surprise you on the day."},{"type":"table","headers":["Paper","What it is","Time","Marks","Date"],"rows":[["Paper 01","60 multiple-choice items (A, B, C, D), covering all of Sections A–E","1 h 15 min","60","Mon 25 Jan 2027"],["Paper 02","Data analysis (Q1), structured and extended-response questions","2 h 30 min","100","Tue 5 Jan 2027"],["Paper 032","Practical-based written paper for alternate (private) candidates, instead of SBA","2 h 10 min","40","Check your timetable"]]},{"type":"remember","text":"There is **no penalty for a wrong answer** in Paper 01. NEVER leave a question blank. If you are stuck, eliminate what you can and guess from the rest."},{"type":"tip","text":"75 minutes ÷ 60 questions ⟪=\\boldsymbol{75}⟫** seconds per question**. Most recall questions take 30 seconds, which buys time for the calculations."}],"n":112},{"id":"week15.15.2","kind":"unit","unit":"15.2","title":"Section B Thermal Physics: Rapid Revision","titleText":"Section B Thermal Physics: Rapid Revision","goals":[{"code":"B","text":"Section B Thermal physics and kinetic theory: temperature, thermometers, gas laws, specific heat and latent heat, heat transfer"}],"codes":["B"],"words":[{"term":"Key","def":"The correct option in a multiple-choice item."},{"term":"Sensitivity","def":"How much an instrument's reading changes for a small change in the quantity."},{"term":"Range","def":"The lowest to highest values an instrument can measure."}],"learn":{"notes":[{"type":"p","text":"Section B items are mostly recall plus two calculations: ⟪E=mc\\Delta \\theta⟫ and ⟪E=ml⟫. Always use KELVIN in gas-law calculations."},{"type":"table","headers":["Topic","Key fact / formula","Unit or trap"],"rows":[["Theories of heat","Caloric theory: heat is a fluid. Kinetic theory: heat is energy of moving particles","Rumford (cannon boring) and Joule disproved caloric"],["Joule","Showed mechanical work turns into a fixed amount of heat (falling weights stirring water)","Heat is a form of ENERGY"],["Temperature","How hot an object is; net heat flows from higher to lower temperature","Related to average KE of the particles"],["Thermometric property","Changes steadily with temperature: liquid length, resistance, emf (thermocouple)",""],["Clinical thermometer","Range 35–43 °C; constriction stops mercury running back; narrow bore = sensitive","Read after removing from the mouth"],["Thermocouple","Wide range, very fast response, small; measures rapidly changing temperatures","Two different metals, two junctions"],["Fixed points","Lower: melting ice 0 °C; upper: steam over boiling water 100 °C (at 1 atm)",""],["Kelvin","⟪T/K=\\theta /{}^{\\circ}\\mathrm{C}+273⟫; absolute zero ⟪=0\\,\\mathrm{K}=-273\\,{}^{\\circ}\\mathrm{C}⟫","⟪27\\,{}^{\\circ}\\mathrm{C}=300\\,\\mathrm{K}⟫"],["Phases","Solid: vibrate in fixed positions. Liquid: close, move around. Gas: far apart, fast, random","Gas molecules hit walls → pressure"],["Expansion","Bimetallic strip bends (thermostat); gaps in rails; water densest at 4 °C","Ice floats, ponds freeze from the top"],["Gas laws","Boyle: pV = constant (T fixed). Charles: ⟪V\\div T⟫ = constant (p fixed). Pressure law: ⟪p\\div T⟫ = constant (V fixed)","General: ⟪p_{1}V_{1}\\div T_{1}=p_{2}V_{2}\\div T_{2}⟫"],["Heat capacity","⟪C=E\\div \\Delta \\theta⟫ (whole object)","J K^−1^"],["Specific heat capacity","⟪E=mc\\Delta \\theta⟫; c of water ⟪=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,\\mathrm{K}^{-1}⟫","J kg^−1^ K^−1^"],["Latent heat","⟪E=ml⟫; temperature stays CONSTANT while melting or boiling","J kg^−1^; energy breaks bonds (raises PE)"],["Evaporation vs boiling","Evaporation: any temperature, surface only, causes cooling. Boiling: fixed temperature, throughout, bubbles",""],["Conduction","Particle vibrations passed on; free electrons in metals","Best in solids, especially metals"],["Convection","Hot fluid expands, becomes less dense, rises; cool fluid sinks","Only in liquids and gases"],["Radiation","Infrared EM waves; needs no medium; travels through a vacuum","Dull black: best absorber AND emitter; shiny silver: worst"],["Vacuum flask","Vacuum stops conduction and convection; silvered walls reduce radiation; stopper stops convection/evaporation",""]]}],"examples":[{"id":"week15.15.2.e1","title":"Specific heat capacity, electrical method","question":"A 50 W heater runs for 120 s and warms a 0.50 kg metal block by 12 °C. Find the specific heat capacity of the metal.","steps":[{"label":"Energy supplied","text":"⟪E=Pt=50\\times 120=6000\\,\\mathrm{J}⟫"},{"label":"Formula","text":"⟪c=E\\div (m\\Delta \\theta )⟫"},{"label":"Substitute","text":"⟪c=6000\\div (0.50\\times 12)=6000\\div 6.0⟫"},{"label":"Answer","text":"⟪c=1000\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,\\mathrm{K}^{-1}⟫"}],"answer":"⟪1000\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,\\mathrm{K}^{-1}\\ (1.0\\times 10^{3}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,\\mathrm{K}^{-1})⟫"},{"id":"week15.15.2.e2","title":"Charles' law: use kelvin","question":"A gas has a volume of 300 cm^3^ at 27 °C. It is heated to 127 °C at constant pressure. What is its new volume?","steps":[{"label":"Convert","text":"⟪T_{1}=27+273=300\\,\\mathrm{K}⟫; ⟪T_{2}=127+273=400\\,\\mathrm{K}⟫"},{"label":"Formula","text":"⟪V_{1}\\div T_{1}=V_{2}\\div T_{2}⟫, so ⟪V_{2}=V_{1}\\times T_{2}\\div T_{1}⟫"},{"label":"Substitute","text":"⟪V_{2}=300\\times 400\\div 300⟫"},{"label":"Answer","text":"⟪V_{2}=400\\,\\mathrm{cm}^{3}⟫"},{"label":"Trap","text":"Using °C gives ⟪300\\times 127\\div 27\\approx 1411\\,\\mathrm{cm}^{3}⟫. That WRONG answer is always one of the options."}],"answer":"400 cm^3^"}]},"tryit":[{"id":"week15.15.2.p1","kind":"mcq","q":"Which scientist showed that mechanical work could be changed into a fixed quantity of heat?","marks":1,"level":1,"options":["Galileo","Newton","Joule","Rutherford"],"answer":"C","explanation":"(1). Joule's falling-weight paddle-wheel experiment showed heat is a form of energy.","section":"try"},{"id":"week15.15.2.p2","kind":"mcq","q":"A temperature of 27 °C on the kelvin scale is","marks":1,"level":1,"options":["300 K","246 K","273 K","327 K"],"answer":"A","explanation":"(1). ⟪T=27+273=300\\,\\mathrm{K}⟫. B subtracts instead of adding.","section":"try"}],"practice":[{"id":"week15.15.2.p3","kind":"mcq","q":"A gas at constant temperature has a pressure of 100 kPa and a volume of 6.0 L. It is compressed to 2.0 L. Its new pressure is","marks":1,"level":1,"options":["33 kPa","300 kPa","200 kPa","600 kPa"],"answer":"B","explanation":"(1). Boyle's law: ⟪p_{2}=p_{1}V_{1}\\div V_{2}=100\\times 6.0\\div 2.0=300\\,\\mathrm{kPa}⟫. Smaller volume means HIGHER pressure, so A cannot be right.","section":"practice"},{"id":"week15.15.2.p4","kind":"mcq","q":"How much energy is needed to raise the temperature of 2.0 kg of water by 5.0 °C? ⟪(c=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,\\mathrm{K}^{-1})⟫","marks":1,"level":1,"options":["8400 J","42 000 J","21 000 J","84 000 J"],"answer":"B","explanation":"(1). ⟪E=mc\\Delta \\theta =2.0\\times 4200\\times 5.0=42\\,000\\,\\mathrm{J}⟫. A leaves out Δθ; C leaves out the mass.","section":"practice"},{"id":"week15.15.2.p5","kind":"mcq","q":"How much energy is needed to melt 0.50 kg of ice at 0 °C? (specific latent heat of fusion ⟪=3.3\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫)","marks":1,"level":1,"options":["⟪1.65\\times 10^{5}\\,\\mathrm{J}⟫","⟪6.6\\times 10^{5}\\,\\mathrm{J}⟫","⟪3.3\\times 10^{5}\\,\\mathrm{J}⟫","⟪1.65\\times 10^{4}\\,\\mathrm{J}⟫"],"answer":"A","explanation":"(1). ⟪E=ml=0.50\\times 3.3\\times 10^{5}=1.65\\times 10^{5}\\,\\mathrm{J}⟫. B divides by 0.50 instead of multiplying.","section":"practice"},{"id":"week15.15.2.p6","kind":"mcq","q":"While a solid is melting, its temperature stays constant because the energy supplied is used to","marks":1,"level":1,"options":["increase the kinetic energy of the molecules","escape to the surroundings","expand the container","break the bonds between the molecules"],"answer":"D","explanation":"(1). Latent heat raises the potential energy (breaks bonds), not the kinetic energy, so the temperature does not rise.","section":"practice"},{"id":"week15.15.2.p7","kind":"mcq","q":"A clinical thermometer has a constriction in its tube in order to","marks":1,"level":1,"options":["make it more sensitive","increase its range","stop the mercury flowing back, so the reading can be taken","make it respond faster"],"answer":"C","explanation":"(1). The constriction holds the mercury in place after the thermometer leaves the mouth. Sensitivity comes from the narrow bore (A).","section":"practice"},{"id":"week15.15.2.p8","kind":"mcq","q":"Evaporation is different from boiling because evaporation","marks":1,"level":1,"options":["takes place at any temperature, from the surface only","takes place only at 100 °C","takes place throughout the liquid","produces bubbles of vapour"],"answer":"A","explanation":"(1). B, C and D all describe boiling.","section":"practice"},{"id":"week15.15.2.p9","kind":"mcq","q":"Which surface is the best emitter of infrared radiation?","marks":1,"level":1,"options":["shiny silver","dull black","shiny white","polished aluminium"],"answer":"B","explanation":"(1). Dull black surfaces are the best absorbers AND the best emitters. Shiny surfaces are poor emitters.","section":"practice"},{"id":"week15.15.2.p10","kind":"mcq","q":"Thermal energy reaches the Earth from the Sun through the vacuum of space by","marks":1,"level":1,"options":["conduction","convection","conduction and convection","radiation"],"answer":"D","explanation":"(1). Conduction and convection need particles. Only radiation (EM waves) crosses a vacuum.","section":"practice"}],"exit":[{"id":"week15.15.2.p11","kind":"mcq","q":"Small gaps are left between sections of a railway line in order to","marks":1,"level":1,"options":["let rain water drain away","reduce the noise of the train","allow the rails to expand in hot weather","save metal"],"answer":"C","explanation":"(1). Metals expand when heated; without gaps the rails would buckle.","section":"exit"},{"id":"week15.15.2.p12","kind":"mcq","q":"A gas in a sealed rigid container at 300 K has a pressure of ⟪1.0\\times 10^{5}\\,\\mathrm{Pa}⟫. It is heated to 450 K. The new pressure is","marks":1,"level":1,"options":["⟪0.67\\times 10^{5}\\,\\mathrm{Pa}⟫","⟪2.0\\times 10^{5}\\,\\mathrm{Pa}⟫","⟪4.5\\times 10^{5}\\,\\mathrm{Pa}⟫","⟪1.5\\times 10^{5}\\,\\mathrm{Pa}⟫"],"answer":"D","explanation":"(1). Pressure law: ⟪p_{2}=p_{1}\\times T_{2}\\div T_{1}=1.0\\times 10^{5}\\times 450\\div 300=1.5\\times 10^{5}\\,\\mathrm{Pa}⟫. Heating raises pressure, so A is wrong.","section":"exit"}],"warmup":[{"id":"week15.15.2.w1","kind":"mcq","q":"A horizontal force of 12 N pushes a 3.0 kg box, but friction of 3.0 N opposes it. The acceleration of the box is","marks":1,"level":1,"options":["4.0 m s^−2^","3.0 m s^−2^","5.0 m s^−2^","36 m s^−2^"],"answer":"B","explanation":"(1). Resultant force ⟪=12-3.0=9.0\\,\\mathrm{N}⟫; ⟪a=F\\div m=9.0\\div 3.0=3.0\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫. A (4.0) ignores friction.","section":"warmup","src":"week15.15.1.p9"},{"id":"week15.15.2.w2","kind":"mcq","q":"A diver is 3.0 m below the surface of water (density 1000 kg m^−3^). The pressure caused by the water at this depth is","marks":1,"level":1,"options":["⟪3.0\\times 10^{4}\\,\\mathrm{Pa}⟫","⟪3.0\\times 10^{2}\\,\\mathrm{Pa}⟫","⟪3.0\\times 10^{3}\\,\\mathrm{Pa}⟫","⟪3.0\\times 10^{5}\\,\\mathrm{Pa}⟫"],"answer":"A","explanation":"(1). ⟪P=\\rho gh=1000\\times 10\\times 3.0=30\\,000\\,\\mathrm{Pa}=3.0\\times 10^{4}\\,\\mathrm{Pa}⟫. C forgets g.","section":"warmup","src":"week15.15.1.p8"},{"id":"week15.15.2.w3","kind":"mcq","q":"The period of a simple pendulum (small swings) depends on","marks":1,"level":1,"options":["the mass of the bob","the material of the bob","the number of swings timed","the length of the string"],"answer":"D","explanation":"(1). T depends only on length ⟪(T^{2}\\propto l)⟫. Galileo showed mass does not matter.","section":"warmup","src":"week15.15.1.p3"}],"n":113},{"id":"week15.15.3","kind":"unit","unit":"15.3","title":"Section C Waves and Optics: Rapid Revision","titleText":"Section C Waves and Optics: Rapid Revision","goals":[{"code":"C","text":"Section C Waves and optics: wave equation, sound, EM spectrum, reflection, refraction, total internal reflection and lenses"}],"codes":["C"],"words":[{"term":"Key","def":"The correct option in a multiple-choice item."}],"learn":{"notes":[{"type":"p","text":"Section C has many short calculation items (⟪v=f\\lambda⟫, echoes, ⟪n=\\sin i\\div \\sin r⟫, lens formula). Learn the formulas and the lens rules."},{"type":"table","headers":["Topic","Key fact / formula","Unit or trap"],"rows":[["Transverse waves","Vibrations at 90° to the direction of travel: light, all EM waves, water ripples","Have crests and troughs"],["Longitudinal waves","Vibrations along the direction of travel: sound","Compressions and rarefactions"],["Wave equation","⟪v=f\\lambda⟫; ⟪T=1\\div f⟫","f in Hz; λ in m; v in m s^−1^"],["Wave graphs","Displacement–DISTANCE graph gives λ; displacement–TIME graph gives T","Amplitude = centre line to crest (NOT crest to trough)"],["Sound","Needs a medium (not a vacuum); about 330 m s^−1^ in air; faster in liquids and solids","Pitch ↔ frequency; loudness ↔ amplitude"],["Echoes","distance = speed × time ÷ 2","Sound goes there AND back"],["Ultrasound","Frequency above 20 kHz: pre-natal scans, sonar, cleaning, finding cracks",""],["EM spectrum","Radio, microwave, infrared, visible, ultraviolet, X-ray, gamma","Left to right: λ DEcreases, f INcreases"],["EM properties","All transverse; all travel at ⟪3.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ in a vacuum; no medium needed",""],["Theories of light","Newton: particles (corpuscles). Huygens: waves. Young's double slit (interference) supports waves","Diffraction of light hard to see: λ is tiny"],["Rectilinear propagation","Light travels in straight lines: shadows, eclipses, pinhole camera (real, inverted image)",""],["Reflection","Angle of incidence = angle of reflection (measured from the NORMAL)",""],["Plane mirror image","Virtual, upright, same size, laterally inverted, as far behind as object is in front",""],["Refraction","Into a denser medium: slows down, bends TOWARDS the normal","Frequency never changes"],["Refractive index","⟪n=\\sin i\\div \\sin r=c\\div v⟫ (speed in vacuum ÷ speed in medium)","No unit; always > 1"],["Critical angle","⟪\\sin c=1\\div n⟫; TIR when going dense → less dense AND angle > c","Uses: optical fibres, prism periscopes"],["Dispersion","Prism splits white light: red bends least, violet bends most","ROYGBIV"],["Lenses","Converging (convex) brings parallel rays to F; diverging (concave) spreads them","Focal length f = lens to F"],["Lens formula","⟪1\\div f=1\\div u+1\\div v⟫; magnification ⟪m=v\\div u⟫ = image height ÷ object height","Object inside F → virtual, upright, magnified (magnifying glass)"]]}],"examples":[{"id":"week15.15.3.e1","title":"Wavelength of a radio wave","question":"A radio station broadcasts at 100 MHz. Find the wavelength. ⟪(c=3.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1})⟫","steps":[{"label":"Formula","text":"⟪\\lambda =v\\div f⟫"},{"label":"Substitute","text":"⟪\\lambda =3.0\\times 10^{8}\\div (100\\times 10^{6})=3.0\\times 10^{8}\\div 1.0\\times 10^{8}⟫"},{"label":"Answer","text":"⟪\\lambda =3.0\\,\\mathrm{m}⟫"}],"answer":"3.0 m (remember ⟪M=10^{6}⟫)"},{"id":"week15.15.3.e2","title":"Refractive index","question":"A ray enters a glass block with angle of incidence 40° and angle of refraction 25°. Find the refractive index.","steps":[{"label":"Formula","text":"⟪n=\\sin i\\div \\sin r⟫"},{"label":"Substitute","text":"⟪n=\\sin 40^{\\circ}\\div \\sin 25^{\\circ}=0.643\\div 0.423⟫"},{"label":"Answer","text":"⟪n=1.52⟫"},{"label":"Sense check","text":"Glass is about 1.5. An answer less than 1 means you divided the wrong way round."}],"answer":"1.52 (no unit)"}]},"tryit":[{"id":"week15.15.3.p1","kind":"mcq","q":"A wave has a frequency of 50 Hz and a wavelength of 4.0 m. Its speed is","marks":1,"level":1,"options":["12.5 m s^−1^","200 m s^−1^","54 m s^−1^","0.08 m s^−1^"],"answer":"B","explanation":"(1). ⟪v=f\\lambda =50\\times 4.0=200\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫. A divides instead of multiplying.","section":"try"},{"id":"week15.15.3.p2","kind":"mcq","q":"The graph shows a wave at one instant. What are its amplitude and wavelength?","marks":1,"level":1,"img":{"src":"img/week15/wave_dp","alt":"The graph shows a wave at one instant. What are its amplitude and wavelength?","w":1054,"h":534},"options":["6 cm and 0.8 m","3 cm and 0.8 m","3 cm and 1.6 m","6 cm and 0.4 m"],"answer":"B","explanation":"(1). Amplitude = centre line to crest = 3 cm (6 cm is crest to trough). One full wave repeats every 0.8 m; 1.6 m contains TWO waves.","section":"try"}],"practice":[{"id":"week15.15.3.p3","kind":"mcq","q":"A boy stands 165 m from a tall wall. He claps and hears the echo 1.0 s later. The speed of sound is","marks":1,"level":1,"options":["165 m s^−1^","660 m s^−1^","82.5 m s^−1^","330 m s^−1^"],"answer":"D","explanation":"(1). The sound travels to the wall and back: ⟪2\\times 165=330\\,\\mathrm{m}⟫ in 1.0 s, so ⟪v=330\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫. A forgets the return trip.","section":"practice"},{"id":"week15.15.3.p4","kind":"mcq","q":"Sound CANNOT travel through","marks":1,"level":1,"options":["water","a vacuum","steel","air"],"answer":"B","explanation":"(1). Sound needs particles to vibrate. A vacuum has none.","section":"practice"},{"id":"week15.15.3.p5","kind":"mcq","q":"Which electromagnetic wave has the longest wavelength?","marks":1,"level":1,"options":["radio waves","gamma rays","X-rays","ultraviolet"],"answer":"A","explanation":"(1). Radio waves are at the long-wavelength (low-frequency) end of the spectrum; gamma is the shortest.","section":"practice"},{"id":"week15.15.3.p6","kind":"mcq","q":"Which of the following is a longitudinal wave?","marks":1,"level":1,"options":["sound","light","radio","a ripple on water"],"answer":"A","explanation":"(1). Sound particles vibrate along the direction of travel. All EM waves and water ripples are transverse.","section":"practice"},{"id":"week15.15.3.p7","kind":"mcq","q":"When light passes from air into glass, it","marks":1,"level":1,"options":["slows down and bends towards the normal","speeds up and bends away from the normal","slows down and bends away from the normal","keeps the same speed and does not bend"],"answer":"A","explanation":"(1). Glass is optically denser: light slows down and bends towards the normal.","section":"practice"},{"id":"week15.15.3.p8","kind":"mcq","q":"The refractive index of a glass is 1.5. The speed of light in the glass is ⟪(c=3.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1})⟫","marks":1,"level":1,"options":["⟪4.5\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","⟪1.5\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","⟪3.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","⟪2.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫"],"answer":"D","explanation":"(1). ⟪v=c\\div n=3.0\\times 10^{8}\\div 1.5=2.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫. Light cannot go faster than c, so A is impossible.","section":"practice"},{"id":"week15.15.3.p9","kind":"mcq","q":"The critical angle of a glass of refractive index 1.5 is closest to","marks":1,"level":1,"options":["30°","48°","56°","42°"],"answer":"D","explanation":"(1). ⟪\\sin c=1\\div 1.5=0.667⟫, so ⟪c=41.8^{\\circ}\\approx 42^{\\circ}⟫. 48° is 90° − 42° (a common slip).","section":"practice"},{"id":"week15.15.3.p10","kind":"mcq","q":"The image of an object in a plane mirror is","marks":1,"level":1,"options":["real, inverted and the same size","virtual, upright and magnified","virtual, upright, the same size and laterally inverted","real, upright and diminished"],"answer":"C","explanation":"(1). A plane mirror image cannot be put on a screen (virtual), is upright, the same size and left–right reversed.","section":"practice"}],"exit":[{"id":"week15.15.3.p11","kind":"mcq","q":"An object is placed 30 cm from a converging lens of focal length 10 cm. The image distance is","marks":1,"level":1,"options":["7.5 cm","20 cm","15 cm","30 cm"],"answer":"C","explanation":"(1). ⟪1\\div v=1\\div f-1\\div u=1\\div 10-1\\div 30=2\\div 30⟫, so ⟪v=15\\,\\mathrm{cm}⟫. 7.5 cm comes from ADDING 1/10 and 1/30.","section":"exit"},{"id":"week15.15.3.p12","kind":"mcq","q":"Which observation is evidence that light behaves as a wave?","marks":1,"level":1,"options":["shadows have sharp edges","light travels in straight lines","bright and dark fringes are seen in Young's double-slit experiment","light is reflected by a mirror"],"answer":"C","explanation":"(1). Interference fringes can only be explained by waves. Particles (Newton) could explain A, B and D.","section":"exit"}],"warmup":[{"id":"week15.15.3.w1","kind":"mcq","q":"While a solid is melting, its temperature stays constant because the energy supplied is used to","marks":1,"level":1,"options":["increase the kinetic energy of the molecules","escape to the surroundings","expand the container","break the bonds between the molecules"],"answer":"D","explanation":"(1). Latent heat raises the potential energy (breaks bonds), not the kinetic energy, so the temperature does not rise.","section":"warmup","src":"week15.15.2.p6"},{"id":"week15.15.3.w2","kind":"mcq","q":"How much energy is needed to melt 0.50 kg of ice at 0 °C? (specific latent heat of fusion ⟪=3.3\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫)","marks":1,"level":1,"options":["⟪1.65\\times 10^{5}\\,\\mathrm{J}⟫","⟪6.6\\times 10^{5}\\,\\mathrm{J}⟫","⟪3.3\\times 10^{5}\\,\\mathrm{J}⟫","⟪1.65\\times 10^{4}\\,\\mathrm{J}⟫"],"answer":"A","explanation":"(1). ⟪E=ml=0.50\\times 3.3\\times 10^{5}=1.65\\times 10^{5}\\,\\mathrm{J}⟫. B divides by 0.50 instead of multiplying.","section":"warmup","src":"week15.15.2.p5"},{"id":"week15.15.3.w3","kind":"mcq","q":"Thermal energy reaches the Earth from the Sun through the vacuum of space by","marks":1,"level":1,"options":["conduction","convection","conduction and convection","radiation"],"answer":"D","explanation":"(1). Conduction and convection need particles. Only radiation (EM waves) crosses a vacuum.","section":"warmup","src":"week15.15.2.p10"}],"n":114},{"id":"week15.15.4","kind":"unit","unit":"15.4","title":"Section D Electricity and Magnetism: Rapid Revision","titleText":"Section D Electricity and Magnetism: Rapid Revision","goals":[{"code":"D","text":"Section D Electricity and magnetism: static, current, circuits, mains, electronics, magnetism, motor effect, induction and transformers"}],"codes":["D"],"words":[{"term":"Key","def":"The correct option in a multiple-choice item."}],"learn":{"notes":[{"type":"p","text":"You covered Section D first in our 1-to-1 sessions (Electrostatics; Current and Circuits; Mains, Electronics, Magnetism and the Motor). This table pulls it all together, with induction and transformers."},{"type":"table","headers":["Topic","Key fact / formula","Unit or trap"],"rows":[["Static charge","Only ELECTRONS move. Gain → negative; lose → positive. Like repel, unlike attract","Charged objects attract neutral ones (induction)"],["Electric field","Region where a charge feels a force; lines go + → −",""],["Static uses/hazards","Uses: photocopier, spray painting, precipitator. Hazards: lightning, fuelling (earth the tanker)",""],["Current","Q = It; conventional current + → −; electrons flow − → +","I in A, Q in C, t in SECONDS"],["Voltage","⟪V=E\\div Q⟫ (energy per coulomb)","⟪V=\\mathrm{J}\\,\\mathrm{C}^{-1}⟫"],["Power and cost","⟪P=IV=I^{2}R⟫; ⟪E=Pt⟫; cost ⟪=\\mathrm{kWh}⟫ × price","⟪\\mathrm{kWh}=\\mathrm{kW}⟫ × hours"],["Ohm's law","⟪V=IR⟫ (ohmic conductor at constant temperature: straight line through origin)","Ω"],["I–V shapes","Ohmic: straight line. Filament lamp: curve (R rises as it heats). Diode: conducts one way only",""],["Series","Same current; voltages add; ⟪R=R_{1}+R_{2}⟫",""],["Parallel","Same voltage; currents add; ⟪1\\div R=1\\div R_{1}+1\\div R_{2}⟫","Total is LESS than the smallest"],["Meters","Ammeter: in series, very LOW resistance. Voltmeter: in parallel, very HIGH resistance",""],["Cells","Primary: cannot be recharged (zinc–carbon). Secondary: rechargeable (lead–acid)",""],["Mains safety","Homes wired in parallel. Fuse/breaker in LIVE wire; fuse just above normal current; earth wire on metal cases","⟪I=P\\div V⟫ to choose a fuse"],["Electronics","Diode: half-wave rectification. AND, OR, NOT, NAND (= NOT AND), NOR (= NOT OR)","Work through gates one at a time"],["Magnets","Iron: temporary (easily magnetised/demagnetised). Steel: permanent. Field lines N → S","Only repulsion proves a magnet"],["Electromagnetism","Current makes a field; right-hand grip rule gives its direction; soft-iron core strengthens it","Relay, bell, circuit breaker"],["Motor effect","Fleming's LEFT-hand rule: thuMb = Motion, First = Field, seCond = Current","Force ↑ with current, field, length"],["Induction","emf induced when magnetic flux CHANGES; bigger with faster motion, more turns, stronger magnet","Lenz: opposes the change"],["Transformer","⟪V_{p}\\div V_{s}=N_{p}\\div N_{s}⟫; ideal: ⟪V_{p}I_{p}=V_{s}I_{s}⟫; works on AC only","High-voltage transmission → low current → less I^2^R loss"]]}],"examples":[{"id":"week15.15.4.e1","title":"Series–parallel circuit","question":"In the circuit, find the ammeter reading and the current through the 6 Ω resistor.","img":{"src":"img/week15/circuit_d","alt":"In the circuit, find the ammeter reading and the current through the 6 Ω resistor.","w":853,"h":574},"steps":[{"label":"Parallel part","text":"⟪1\\div R=1\\div 6+1\\div 12=3\\div 12⟫, so ⟪R=4\\,\\Omega⟫"},{"label":"Total","text":"⟪R_{T}=4+4=8\\,\\Omega⟫"},{"label":"Current","text":"⟪I=V\\div R=12\\div 8=1.5\\,\\mathrm{A}⟫"},{"label":"Voltage across parallel part","text":"⟪V=IR=1.5\\times 4=6.0\\,\\mathrm{V}⟫"},{"label":"6 Ω branch","text":"⟪I=6.0\\div 6=1.0\\,\\mathrm{A}⟫ (and 0.5 A through 12 Ω: ⟪1.0+0.5=1.5\\,\\mathrm{A}⟫ ✓)"}],"answer":"Ammeter 1.5 A; 1.0 A through the 6 Ω resistor"},{"id":"week15.15.4.e2","title":"Ideal transformer","question":"An ideal transformer steps 240 V down to 12 V. The secondary current is 2.0 A. Find the primary current.","steps":[{"label":"Formula","text":"⟪V_{p}I_{p}=V_{s}I_{s}⟫"},{"label":"Substitute","text":"⟪240\\times I_{p}=12\\times 2.0=24⟫"},{"label":"Answer","text":"⟪I_{p}=24\\div 240=0.10\\,\\mathrm{A}⟫"}],"answer":"0.10 A (step DOWN voltage → step UP current, and vice versa)"}]},"tryit":[{"id":"week15.15.4.p1","kind":"mcq","q":"A balloon rubbed on hair sticks to a neutral wall. This is because the balloon","marks":1,"level":1,"options":["loses all its charge to the wall","has the same charge as the wall","is magnetised by rubbing","induces an opposite charge on the nearby surface of the wall"],"answer":"D","explanation":"(1). The charged balloon pushes or pulls electrons in the wall, leaving an opposite charge closest to it; unlike charges attract.","section":"try"},{"id":"week15.15.4.p2","kind":"mcq","q":"A current of 0.50 A flows for 2 minutes. The charge that flows is","marks":1,"level":1,"options":["1.0 C","60 C","240 C","0.0042 C"],"answer":"B","explanation":"(1). Q = It ⟪=0.50\\times 120\\,\\mathrm{s}=60\\,\\mathrm{C}⟫. A uses 2 instead of 120 seconds.","section":"try"}],"practice":[{"id":"week15.15.4.p3","kind":"mcq","q":"A 6 Ω resistor and a 3 Ω resistor are connected in parallel. Their combined resistance is","marks":1,"level":1,"options":["9 Ω","4.5 Ω","2 Ω","0.5 Ω"],"answer":"C","explanation":"(1). ⟪1\\div R=1/6+1/3=3/6⟫, so ⟪R=2\\,\\Omega⟫. It must be less than 3 Ω, so A and B are wrong; 0.5 is 1/R, not R.","section":"practice"},{"id":"week15.15.4.p4","kind":"mcq","q":"In the circuit shown, the reading on the ammeter is","marks":1,"level":1,"img":{"src":"img/week15/circuit_d","alt":"In the circuit shown, the reading on the ammeter is","w":853,"h":574},"options":["1.0 A","3.0 A","0.5 A","1.5 A"],"answer":"D","explanation":"(1). Parallel 6 Ω and ⟪12\\,\\Omega =4\\,\\Omega⟫; total 8 Ω; ⟪I=12\\div 8=1.5\\,\\mathrm{A}⟫. 1.0 A is the current in the 6 Ω branch only.","section":"practice"},{"id":"week15.15.4.p5","kind":"mcq","q":"A 2000 W kettle is used for 30 minutes each day for 30 days. Electricity costs $0.80 per kWh. The cost is","marks":1,"level":1,"options":["$48.00","$1.60","$24 000","$24.00"],"answer":"D","explanation":"(1). ⟪E=2.0\\,\\mathrm{kW}\\times 0.5\\,\\mathrm{h}\\times 30=30\\,\\mathrm{kWh}⟫; cost ⟪=30\\times 0.80=\\$24.00⟫. C forgets to change W to kW.","section":"practice"},{"id":"week15.15.4.p6","kind":"mcq","q":"A 1150 W appliance works on a 115 V supply. Fuses of 3 A, 5 A, 13 A and 30 A are available. The best fuse to use is","marks":1,"level":1,"options":["13 A","3 A","5 A","30 A"],"answer":"A","explanation":"(1). ⟪I=P\\div V=1150\\div 115=10\\,\\mathrm{A}⟫. Choose the fuse just ABOVE 10 A: 13 A. 30 A would not protect the appliance.","section":"practice"},{"id":"week15.15.4.p7","kind":"mcq","q":"Which logic gate gives an output of 0 ONLY when both inputs are 1?","marks":1,"level":1,"options":["AND","OR","NAND","NOR"],"answer":"C","explanation":"(1). NAND = NOT AND. AND gives 1 only when both are 1, so NAND gives 0 only then.","section":"practice"},{"id":"week15.15.4.p8","kind":"mcq","q":"For the logic circuit shown, which set of inputs gives an output ⟪Q=0⟫?","marks":1,"level":1,"img":{"src":"img/week15/logic","alt":"For the logic circuit shown, which set of inputs gives an output Q = 0?","w":1054,"h":408},"options":["⟪A=1⟫, ⟪B=1⟫, ⟪C=0⟫","⟪A=0⟫, ⟪B=0⟫, ⟪C=1⟫","⟪A=1⟫, ⟪B=0⟫, ⟪C=0⟫","⟪A=0⟫, ⟪B=1⟫, ⟪C=1⟫"],"answer":"C","explanation":"(1). ⟪P=A⟫ AND B; ⟪Q=P⟫ OR C. Option C: ⟪P=0⟫ and input ⟪C=0⟫, so ⟪Q=0⟫. In option A, ⟪P=1⟫; in options B and D, input ⟪C=1⟫, so ⟪Q=1⟫.","section":"practice"},{"id":"week15.15.4.p9","kind":"mcq","q":"A single diode is connected to an AC supply and a resistor. The current through the resistor is","marks":1,"level":1,"options":["steady DC","half-wave rectified (flows in one direction, in pulses)","AC with double the frequency","zero"],"answer":"B","explanation":"(1). The diode lets current through only in one direction, so half of each cycle is removed.","section":"practice"},{"id":"week15.15.4.p10","kind":"mcq","q":"Soft iron is used for the core of an electromagnet because it","marks":1,"level":1,"options":["is easily magnetised and demagnetised","is a permanent magnet","is a good electrical insulator","does not conduct heat"],"answer":"A","explanation":"(1). The magnet must switch OFF when the current stops, so a temporary magnetic material (iron) is needed. Steel would stay magnetised.","section":"practice"}],"exit":[{"id":"week15.15.4.p11","kind":"mcq","q":"A transformer has 600 turns on the primary coil and 30 turns on the secondary coil. The primary voltage is 120 V. The secondary voltage is","marks":1,"level":1,"options":["2400 V","6.0 V","12 V","0.15 V"],"answer":"B","explanation":"(1). ⟪V_{s}=V_{p}\\times N_{s}\\div N_{p}=120\\times 30\\div 600=6.0\\,\\mathrm{V}⟫. Fewer secondary turns → step-down; A is upside down.","section":"exit"},{"id":"week15.15.4.p12","kind":"mcq","q":"The force on a current-carrying wire in a magnetic field is increased by","marks":1,"level":1,"options":["increasing the current","reversing the current","using a weaker magnet","shortening the length of wire in the field"],"answer":"A","explanation":"(1). Force increases with current, field strength and length in the field. Reversing the current only reverses the direction.","section":"exit"}],"warmup":[{"id":"week15.15.4.w1","kind":"mcq","q":"Which observation is evidence that light behaves as a wave?","marks":1,"level":1,"options":["shadows have sharp edges","light travels in straight lines","bright and dark fringes are seen in Young's double-slit experiment","light is reflected by a mirror"],"answer":"C","explanation":"(1). Interference fringes can only be explained by waves. Particles (Newton) could explain A, B and D.","section":"warmup","src":"week15.15.3.p12"},{"id":"week15.15.4.w2","kind":"mcq","q":"Which electromagnetic wave has the longest wavelength?","marks":1,"level":1,"options":["radio waves","gamma rays","X-rays","ultraviolet"],"answer":"A","explanation":"(1). Radio waves are at the long-wavelength (low-frequency) end of the spectrum; gamma is the shortest.","section":"warmup","src":"week15.15.3.p5"},{"id":"week15.15.4.w3","kind":"mcq","q":"The refractive index of a glass is 1.5. The speed of light in the glass is ⟪(c=3.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1})⟫","marks":1,"level":1,"options":["⟪4.5\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","⟪1.5\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","⟪3.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","⟪2.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫"],"answer":"D","explanation":"(1). ⟪v=c\\div n=3.0\\times 10^{8}\\div 1.5=2.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫. Light cannot go faster than c, so A is impossible.","section":"warmup","src":"week15.15.3.p8"}],"n":115},{"id":"week15.15.5","kind":"unit","unit":"15.5","title":"Section E The Physics of the Atom: Rapid Revision","titleText":"Section E The Physics of the Atom: Rapid Revision","goals":[{"code":"E","text":"Section E The physics of the atom: atomic models, structure, radioactivity, half-life, nuclear equations and uses"}],"codes":["E"],"words":[{"term":"Key","def":"The correct option in a multiple-choice item."},{"term":"Range","def":"The lowest to highest values an instrument can measure."}],"learn":{"notes":[{"type":"p","text":"Section E is the smallest section but full of easy marks: models of the atom, α/β/γ properties, nuclear equations and half-life."},{"type":"table","headers":["Topic","Key fact / formula","Unit or trap"],"rows":[["Dalton","Atoms are tiny, indivisible spheres",""],["Thomson","Discovered the electron; 'plum-pudding' model (electrons in a positive sphere)",""],["Rutherford","Nuclear model: tiny, dense, positive nucleus with electrons outside","From the Geiger–Marsden experiment"],["Geiger–Marsden","α at gold foil: most pass straight through → mostly empty space; a few bounce back → small dense + nucleus",""],["Bohr / Chadwick","Bohr: electrons in fixed shells (energy levels). Chadwick: discovered the neutron (1932)",""],["Particles","Proton: +1, mass 1. Neutron: 0, mass 1. Electron: −1, mass ≈ 1/1840","Atom neutral: protons = electrons"],["Notation","⟪A=Z+N⟫ (nucleon number = protons + neutrons)","⟪N=A-Z⟫"],["Isotopes","Same Z (protons), different N (neutrons); same chemistry",""],["Shells","2, 8, 8 …; outer electrons decide chemistry and place in the periodic table",""],["Marie Curie","Studied radioactivity; discovered polonium and radium; two Nobel prizes; died from radiation exposure",""],["Alpha (α)","Helium nucleus ⟪(2p+2n)⟫, charge +2; stopped by paper or a few cm of air; most ionising","⟪A-4⟫, ⟪Z-2⟫"],["Beta (β)","Fast electron from the nucleus, charge −1; stopped by a few mm of aluminium","A same, ⟪Z+1⟫"],["Gamma (γ)","EM wave, no charge, no mass; reduced by thick lead or concrete; least ionising","No change to A or Z"],["Deflection","In a field α and β bend OPPOSITE ways; β bends more (lighter); γ not deflected",""],["Cloud chamber","α: short, thick, straight tracks. β: thin, wiggly. γ: hardly any track",""],["Decay","Random and spontaneous; NOT affected by temperature, pressure or chemical state",""],["Half-life","Time for half the nuclei (or the activity) to decay; constant for an isotope","After n half-lives: fraction ⟪=(\\tfrac{1}{2})^{n}⟫"],["Uses","Tracers, radiotherapy (Co-60), sterilising, thickness gauges (β), smoke detectors (α, Am-241), carbon dating (C-14, 5730 years)",""],["⟪E=mc^{2}⟫","Mass lost (mass defect) becomes energy; ⟪c=3.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","m in kg, E in J"],["Nuclear power","For: no CO~2~, huge energy from small fuel mass. Against: radioactive waste, accident risk, high cost",""]]}],"examples":[{"id":"week15.15.5.e1","title":"Half-life","question":"A sample contains 64 g of a radioisotope with a half-life of 3 hours. How much is left after 12 hours?","steps":[{"label":"Number of half-lives","text":"⟪n=12\\div 3=4⟫"},{"label":"Halve 4 times","text":"64 → 32 → 16 → 8 → 4"},{"label":"Answer","text":"4 g remain"}],"answer":"4 g (NOT 0 g: a half-life never removes everything)"},{"id":"week15.15.5.e2","title":"Balancing a beta decay","question":"Carbon-⟪14\\ (Z=6)⟫ decays by beta emission. What nucleus is formed?","steps":[{"label":"Rule","text":"β decay: A stays the same, Z goes up by 1 (a neutron becomes a proton + electron)"},{"label":"Apply","text":"⟪A=14⟫; ⟪Z=6+1=7⟫"},{"label":"Answer","text":"⟪Z=7⟫ is nitrogen, so nitrogen-14 is formed"},{"label":"Check","text":"Top: ⟪14=14+0⟫ ✓  Bottom: ⟪6=7+(-1)⟫ ✓"}],"answer":"Nitrogen-14 (A = 14, ⟪Z=7⟫)"}]},"tryit":[{"id":"week15.15.5.p1","kind":"mcq","q":"In the Geiger–Marsden experiment, most alpha particles passed straight through the gold foil. This showed that","marks":1,"level":1,"options":["the nucleus is positive","the atom is mostly empty space","electrons orbit in shells","gold atoms are very small"],"answer":"B","explanation":"(1). Straight-through means nothing was in the way. The FEW large deflections showed the small, dense, positive nucleus (A).","section":"try"},{"id":"week15.15.5.p2","kind":"mcq","q":"A uranium nucleus has nucleon number 238 and proton number 92. How many neutrons does it have?","marks":1,"level":1,"options":["92","238","146","330"],"answer":"C","explanation":"(1). ⟪N=A-Z=238-92=146⟫. D adds instead of subtracting.","section":"try"}],"practice":[{"id":"week15.15.5.p3","kind":"mcq","q":"Isotopes of an element have the same number of","marks":1,"level":1,"options":["neutrons","protons","nucleons","mass number"],"answer":"B","explanation":"(1). Isotopes have the same proton number (so they are the same element) but different numbers of neutrons.","section":"practice"},{"id":"week15.15.5.p4","kind":"mcq","q":"Radium-⟪226\\ (Z=88)⟫ emits an alpha particle. The new nucleus has","marks":1,"level":1,"options":["⟪A=226⟫, ⟪Z=89⟫","⟪A=222⟫, ⟪Z=88⟫","⟪A=222⟫, ⟪Z=86⟫","⟪A=226⟫, ⟪Z=87⟫"],"answer":"C","explanation":"(1). α = helium nucleus: A falls by 4 (226 → 222) and Z falls by 2 (88 → 86). A is beta decay.","section":"practice"},{"id":"week15.15.5.p5","kind":"mcq","q":"When a nucleus emits a beta particle, its","marks":1,"level":1,"options":["proton number increases by 1 and nucleon number stays the same","nucleon number falls by 4","proton number decreases by 1","nucleon number increases by 1"],"answer":"A","explanation":"(1). A neutron changes into a proton and an electron; the electron is emitted. ⟪Z+1⟫, A unchanged.","section":"practice"},{"id":"week15.15.5.p6","kind":"mcq","q":"Which radiation is stopped by a sheet of paper?","marks":1,"level":1,"options":["alpha","beta","gamma","X-rays"],"answer":"A","explanation":"(1). Alpha is large and highly ionising, so it is stopped by paper. Beta needs aluminium; gamma needs thick lead.","section":"practice"},{"id":"week15.15.5.p7","kind":"mcq","q":"A sample has an activity of 800 counts per minute. Its half-life is 2 days. What is its activity after 6 days?","marks":1,"level":1,"options":["100 counts per minute","400 counts per minute","200 counts per minute","0 counts per minute"],"answer":"A","explanation":"(1). ⟪6\\div 2=3⟫ half-lives: 800 → 400 → 200 → 100. B is after only one half-life.","section":"practice"},{"id":"week15.15.5.p8","kind":"mcq","q":"The graph shows how the activity of a radioactive sample changes with time. The half-life is","marks":1,"level":1,"img":{"src":"img/week15/decay","alt":"The graph shows how the activity of a radioactive sample changes with time. The half-life is","w":934,"h":574},"options":["2.5 min","5 min","10 min","40 min"],"answer":"B","explanation":"(1). Activity falls from 80 to 40 counts per second in 5 min (and 40 → 20 in another 5 min). 10 min is two half-lives.","section":"practice"},{"id":"week15.15.5.p9","kind":"mcq","q":"Which statement about radioactive decay is correct?","marks":1,"level":1,"options":["It speeds up when the sample is heated","It stops at very low temperatures","The half-life gets longer as the sample gets smaller","It is random and spontaneous"],"answer":"D","explanation":"(1). Decay cannot be predicted for one nucleus and is not affected by temperature or pressure. The half-life is constant.","section":"practice"},{"id":"week15.15.5.p10","kind":"mcq","q":"Smoke detectors usually contain a source of","marks":1,"level":1,"options":["beta particles","gamma rays","X-rays","alpha particles"],"answer":"D","explanation":"(1). Americium-241 emits alpha. Alpha ionises the air strongly but has a short range, so it is safe inside the detector.","section":"practice"}],"exit":[{"id":"week15.15.5.p11","kind":"mcq","q":"Marie Curie is best known for","marks":1,"level":1,"options":["discovering the neutron","discovering the nucleus","discovering the elements radium and polonium","discovering the electron"],"answer":"C","explanation":"(1). Chadwick found the neutron (A), Rutherford the nucleus (B) and Thomson the electron (D).","section":"exit"},{"id":"week15.15.5.p12","kind":"mcq","q":"In a nuclear reaction, the mass lost is ⟪1.0\\times 10^{-28}\\,\\mathrm{kg}⟫. The energy released is ⟪(c=3.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1})⟫","marks":1,"level":1,"options":["⟪3.0\\times 10^{-20}\\,\\mathrm{J}⟫","⟪9.0\\times 10^{-11}\\,\\mathrm{J}⟫","⟪3.0\\times 10^{-12}\\,\\mathrm{J}⟫","⟪9.0\\times 10^{-12}\\,\\mathrm{J}⟫"],"answer":"D","explanation":"(1). ⟪E=mc^{2}=1.0\\times 10^{-28}\\times (3.0\\times 10^{8})^{2}=1.0\\times 10^{-28}\\times 9.0\\times 10^{16}=9.0\\times 10^{-12}\\,\\mathrm{J}⟫. A forgets to square c.","section":"exit"}],"warmup":[{"id":"week15.15.5.w1","kind":"mcq","q":"Which logic gate gives an output of 0 ONLY when both inputs are 1?","marks":1,"level":1,"options":["AND","OR","NAND","NOR"],"answer":"C","explanation":"(1). NAND = NOT AND. AND gives 1 only when both are 1, so NAND gives 0 only then.","section":"warmup","src":"week15.15.4.p7"},{"id":"week15.15.5.w2","kind":"mcq","q":"A single diode is connected to an AC supply and a resistor. The current through the resistor is","marks":1,"level":1,"options":["steady DC","half-wave rectified (flows in one direction, in pulses)","AC with double the frequency","zero"],"answer":"B","explanation":"(1). The diode lets current through only in one direction, so half of each cycle is removed.","section":"warmup","src":"week15.15.4.p9"},{"id":"week15.15.5.w3","kind":"mcq","q":"A balloon rubbed on hair sticks to a neutral wall. This is because the balloon","marks":1,"level":1,"options":["loses all its charge to the wall","has the same charge as the wall","is magnetised by rubbing","induces an opposite charge on the nearby surface of the wall"],"answer":"D","explanation":"(1). The charged balloon pushes or pulls electrons in the wall, leaving an opposite charge closest to it; unlike charges attract.","section":"warmup","src":"week15.15.4.p1"}],"n":116},{"id":"week15.15.6","kind":"unit","unit":"15.6","title":"MCQ Technique: Fast and Accurate","titleText":"MCQ Technique: Fast and Accurate","goals":[{"code":"P01","text":"Paper 01 technique: answer 60 MCQs in 75 minutes using elimination, unit checks, estimating and fast graph reading"}],"codes":["P01"],"words":[{"term":"Stem","def":"The question part of a multiple-choice item."},{"term":"Key","def":"The correct option in a multiple-choice item."},{"term":"Elimination","def":"Crossing out options you know are wrong before choosing."}],"learn":{"notes":[{"type":"p","text":"Knowing the physics is half the job. The other half is **technique**: getting through 60 questions in 75 minutes without careless errors. Practise these methods on every MCQ in this book."},{"type":"h","text":"The 5-step method for every question"},{"type":"steps","items":["**Read the stem** (the question part) carefully. Underline key words: NOT, EXCEPT, MOST, LEAST, BEST, units.","**Cover the options** and predict the answer in your head first.","**Look at the options.** If your prediction is there, check it once and choose it.","If not, **eliminate** the options you know are wrong. Cross them out on the question paper.","**Shade** the answer sheet carefully, in the right row. Move on."]},{"type":"h","text":"Five power techniques"},{"type":"table","headers":["Technique","How to use it","Example"],"rows":[["Elimination","Cross out impossible options first. With 2 left, your guess is 50% instead of 25%","Efficiency 133%? Impossible. Speed > ⟪3\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫? Impossible"],["Units check","Work out the unit of the answer from the formula. Options with the wrong unit are wrong","⟪mgh\\div t\\rightarrow J\\div s=W⟫, so the answer is a power"],["Estimating","Round the numbers and work out the size (power of ten). Options are often 10× apart","⟪0.48\\times 9.8\\times 2.1\\approx 0.5\\times 10\\times 2=10⟫"],["Reading graphs fast","Read the AXES and UNITS first. Then ask: gradient, area or a read-off?","v–t: gradient = acceleration, area = distance"],["I, II, III items","Decide each statement TRUE or FALSE separately, then find the option that matches","I ✓ II ✓ III ✗ → 'I and II only'"]]},{"type":"h","text":"Timing: 75 seconds per question"},{"type":"table","headers":["Checkpoint","Question number","Time used (aim)"],"rows":[["1","Q15 done","16 min"],["2","Q30 done","32 min"],["3","Q45 done","48 min"],["4","Q60 done","64 min"],["Check","Return to starred items; check shading","64–75 min"]]},{"type":"tip","text":"If a question takes more than 90 seconds, put a star next to it, choose your best guess NOW, and move on. Come back at the end if there is time. Never let one hard question steal time from three easy ones.","label":"TWO-PASS STRATEGY"},{"type":"warn","text":"Shading errors. If you skip a question, make sure the next answer goes in the right row. Check every 10 questions that the question number matches the answer-sheet row."},{"type":"remember","text":"The trap answer is usually what you get from one common mistake: forgetting to square, using minutes instead of seconds, using °C instead of K, adding instead of subtracting. If your answer matches an option, ask 'could I have made the classic mistake?'"}],"examples":[{"id":"week15.15.6.e1","title":"Elimination","question":"A lamp is rated 60 W. In one minute it gives out 300 J of light energy. What is its efficiency? (A) 5% (B) 8.3% (C) 20% (D) 120%","steps":[{"label":"Eliminate","text":"D is impossible (more than 100%)."},{"label":"Input","text":"⟪E=Pt=60\\times 60\\,\\mathrm{s}=3600\\,\\mathrm{J}⟫"},{"label":"Efficiency","text":"⟪300\\div 3600\\times 100\\%=8.3\\%⟫"},{"label":"Trap","text":"Using ⟪t=1⟫ (minute) gives ⟪300\\div 60=5\\ (A)⟫, or ⟪60\\div 300=20\\%\\ (C)⟫."}],"answer":"B (8.3%)"},{"id":"week15.15.6.e2","title":"Units check","question":"Which expression has the unit of momentum? ⟪(A)mv^{2}\\ (B)Ft\\ (C)Fd\\ (D)m\\div v⟫","steps":[{"label":"Momentum unit","text":"⟪p=mv\\rightarrow \\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫"},{"label":"Test B","text":"⟪Ft\\rightarrow N\\times s=\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-2}\\times s=\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ ✓"},{"label":"Others","text":"mv^2^ and Fd are energy units (J); ⟪m\\div v⟫ is kg s m^−1^"}],"answer":"B (Ft = change in momentum, the impulse)"},{"id":"week15.15.6.e3","title":"Estimating","question":"A 0.48 kg book falls ⟪2.1\\,\\mathrm{m}\\ (g=9.8\\,\\mathrm{N}\\,\\mathrm{kg}^{-1})⟫. The energy lost is about (A) 0.1 J (B) 1 J (C) 10 J (D) 100 J","steps":[{"label":"Round","text":"⟪mgh\\approx 0.5\\times 10\\times 2=10\\,\\mathrm{J}⟫"},{"label":"Check","text":"Exact: ⟪0.48\\times 9.8\\times 2.1=9.9\\,\\mathrm{J}⟫ ✓"}],"answer":"C (about 10 J)"}]},"tryit":[{"id":"week15.15.6.p1","kind":"mcq","q":"The quantity ⟪mgh\\div t⟫ has the unit","marks":1,"level":1,"options":["W","J","N","Pa"],"answer":"A","explanation":"(1). mgh is energy (J); ⟪J\\div s=W⟫. **Technique: units check.**","section":"try"},{"id":"week15.15.6.p2","kind":"mcq","q":"A student of mass 60 kg runs up stairs 3.0 m high in 4.0 s. Her power is about","marks":1,"level":1,"options":["4.5 W","45 W","450 W","4500 W"],"answer":"C","explanation":"(1). ⟪P=mgh\\div t=60\\times 10\\times 3.0\\div 4.0=450\\,\\mathrm{W}⟫. **Technique: estimate** ⟪(600\\times 3\\div 4\\approx 450)⟫; the options are 10× apart.","section":"try"}],"practice":[{"id":"week15.15.6.p3","kind":"mcq","q":"A graph of y against x is a straight line through the origin. This shows that","marks":1,"level":1,"options":["y is directly proportional to x","y is constant","y is inversely proportional to x","y decreases as x increases"],"answer":"A","explanation":"(1). Straight line + through the origin = direct proportion. **Technique: reading graphs fast.**","section":"practice"},{"id":"week15.15.6.p4","kind":"mcq","q":"Which of the following is NOT a vector quantity?","marks":1,"level":1,"options":["force","velocity","displacement","time"],"answer":"D","explanation":"(1). Time has no direction. **Technique: underline NOT** before you start; A, B and C are all vectors.","section":"practice"}],"exit":[{"id":"week15.15.6.p5","kind":"mcq","q":"Which of the following increase the pressure at the bottom of a tank of liquid? I Increasing the depth of liquid  II Using a denser liquid  III Using a wider tank","marks":1,"level":1,"options":["I only","I and II only","II and III only","I, II and III"],"answer":"B","explanation":"(1). ⟪P=\\rho gh⟫: depth ✓ (I), density ✓ (II); width does not appear in the formula ✗ (III). **Technique: true/false each statement.**","section":"exit"},{"id":"week15.15.6.p6","kind":"mcq","q":"The speed of a car on a highway is most likely to be","marks":1,"level":1,"options":["0.25 m s^−1^","25 m s^−1^","250 m s^−1^","2500 m s^−1^"],"answer":"B","explanation":"(1). ⟪25\\,\\mathrm{m}\\,\\mathrm{s}^{-1}=90\\,\\mathrm{km}\\,\\mathrm{h}^{-1}⟫. 250 m s^−1^ is a jet airliner. **Technique: sense check / estimating.**","section":"exit"}],"warmup":[{"id":"week15.15.6.w1","kind":"mcq","q":"Which radiation is stopped by a sheet of paper?","marks":1,"level":1,"options":["alpha","beta","gamma","X-rays"],"answer":"A","explanation":"(1). Alpha is large and highly ionising, so it is stopped by paper. Beta needs aluminium; gamma needs thick lead.","section":"warmup","src":"week15.15.5.p6"},{"id":"week15.15.6.w2","kind":"mcq","q":"In a nuclear reaction, the mass lost is ⟪1.0\\times 10^{-28}\\,\\mathrm{kg}⟫. The energy released is ⟪(c=3.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1})⟫","marks":1,"level":1,"options":["⟪3.0\\times 10^{-20}\\,\\mathrm{J}⟫","⟪9.0\\times 10^{-11}\\,\\mathrm{J}⟫","⟪3.0\\times 10^{-12}\\,\\mathrm{J}⟫","⟪9.0\\times 10^{-12}\\,\\mathrm{J}⟫"],"answer":"D","explanation":"(1). ⟪E=mc^{2}=1.0\\times 10^{-28}\\times (3.0\\times 10^{8})^{2}=1.0\\times 10^{-28}\\times 9.0\\times 10^{16}=9.0\\times 10^{-12}\\,\\mathrm{J}⟫. A forgets to square c.","section":"warmup","src":"week15.15.5.p12"},{"id":"week15.15.6.w3","kind":"mcq","q":"Smoke detectors usually contain a source of","marks":1,"level":1,"options":["beta particles","gamma rays","X-rays","alpha particles"],"answer":"D","explanation":"(1). Americium-241 emits alpha. Alpha ionises the air strongly but has a short range, so it is safe inside the detector.","section":"warmup","src":"week15.15.5.p10"}],"n":117},{"id":"week15.15.7","kind":"unit","unit":"15.7","title":"Paper 032 Practical Skills (only if you are an alternate candidate)","titleText":"Paper 032 Practical Skills (only if you are an alternate candidate)","goals":[{"code":"P032","text":"Paper 032 practical skills (alternate candidates only): reading instruments, tables, graphs, precautions, errors and planning"},{"code":"A","text":"Section A Mechanics: measurement, vectors, forces, moments, motion, momentum, energy, power and pressure"}],"codes":["P032","A"],"words":[{"term":"Precision","def":"How close repeated readings are to each other; also the smallest division read."},{"term":"Range","def":"The lowest to highest values an instrument can measure."},{"term":"Zero error","def":"An instrument shows a reading when it should read zero; a systematic error."},{"term":"Random error","def":"Error that varies unpredictably; reduced by repeating and averaging."},{"term":"Systematic error","def":"Error that is the same every time (e.g. zero error); not removed by averaging."},{"term":"Fiducial mark","def":"A fixed reference mark (e.g. at the centre of a pendulum swing) used for counting oscillations."},{"term":"Hypothesis","def":"A testable statement predicting how one variable affects another."}],"learn":{"notes":[{"type":"warn","text":"Paper 032 is the practical-based written paper taken by **alternate (private) candidates instead of the School-Based Assessment (SBA)**. Check your exam entry slip. If it shows Paper 032, this unit is for you. If you have SBA marks (from school, or carried forward), you can skip it, although these skills also earn marks in Paper 02 Question 1.","label":"READ THIS FIRST"},{"type":"h","text":"1. Reading instruments"},{"type":"table","headers":["Instrument","Smallest division","How to read","Watch out for"],"rows":[["Metre rule","1 mm (0.1 cm)","Eye directly above the mark","Parallax; worn zero end"],["Vernier calipers","0.1 mm (0.01 cm)","Main scale before vernier zero + (vernier line that lines up × 0.01 cm)","Zero error (close jaws first)"],["Micrometer","0.01 mm","Sleeve (mm and half-mm) + thimble line on the datum × 0.01 mm","Use the ratchet; zero error"],["Thermometer","Usually 1 °C","Eye level with the end of the liquid; stir first","Bulb touching the container"],["Ammeter / voltmeter","Work out what one small division is worth","Eye directly in front of the pointer (mirror strip)","Zero error; wrong range"],["Measuring cylinder","Usually 1 cm^3^","Eye level with the BOTTOM of the meniscus","Parallax"],["Stopwatch","0.01 s","Time many oscillations (e.g. 20) and divide","Reaction time ≈ 0.2 s"]]},{"type":"img","src":"img/week15/vernier","alt":"Figure 15.1 — Vernier: main scale 3.4 cm; vernier line 6 lines up → 3.4 + 0.06 = 3.46 cm","caption":"Figure 15.1 — Vernier: main scale 3.4 cm; vernier line 6 lines up → ⟪3.4+0.06=3.46\\,\\mathrm{cm}⟫","width":5.6,"w":1270,"h":414},{"type":"h","text":"2. Recording results in a table"},{"type":"bullets","items":["Each column heading = **quantity / unit**, e.g. *length, l / m* or *time for 20 oscillations, t / s*. Units go in the heading, NOT next to each number.","Put the quantity you **changed** (independent variable) in the first column.","Record every reading to the **same number of decimal places** (the precision of the instrument).","Leave room for repeat readings and an average. Calculated values are usually given to the same number of significant figures as the data (or one more)."]},{"type":"h","text":"3. Plotting a graph"},{"type":"img","src":"img/week15/good_graph","alt":"Figure 15.2 — Features of a well-drawn graph (T2 against l for a pendulum)","caption":"Figure 15.2 — Features of a well-drawn graph (T^2^ against l for a pendulum)","width":4.8,"w":1087,"h":733},{"type":"bullets","items":["'Plot y against x': the first quantity named goes on the **y-axis**.","Label both axes with **quantity / unit**. Choose an even scale (1, 2, 5 or 10 per large square, never 3 or 7) that uses **more than half** the grid.","Plot points accurately as small × or ⊙. Draw ONE thin line of best fit (straight or smooth curve) with points evenly on both sides. Do not join dot to dot.","Gradient: draw a LARGE triangle (more than half the line); gradient ⟪=\\Delta y\\div \\Delta x⟫, WITH units. Use points on the LINE, not data points."]},{"type":"h","text":"4. Precautions and sources of error"},{"type":"table","headers":["Experiment","Precautions (say WHY)","Main sources of error"],"rows":[["Simple pendulum","Small amplitude (< 10°); time 20 oscillations; use a fiducial mark at the centre; measure l to the centre of the bob","Reaction time; counting oscillations wrongly; parallax measuring l"],["I–V / resistance","Switch off between readings so the wire does not heat up; check meter zero; good tight connections","Heating changes resistance; meter zero error; parallax reading meters"],["Specific heat (electrical)","Insulate (lag) the block; stir or use oil in thermometer hole; read thermometer at eye level","Heat lost to the surroundings; heater not fully in contact"],["Hooke's law","Do not exceed the limit of proportionality; read the pointer at eye level; let the spring settle","Parallax; spring not returning to original length"]]},{"type":"remember","text":"A **precaution** is something you DO to make the result more accurate. 'Be careful' and 'repeat the experiment' alone get no marks: say exactly what you do and why."},{"type":"h","text":"5. Planning and designing an investigation"},{"type":"table","headers":["Heading","What to write"],"rows":[["Hypothesis","A testable statement, e.g. 'The thicker the insulation, the slower the water cools.'"],["Aim","To investigate how [independent variable] affects [dependent variable]."],["Apparatus","List everything, including measuring instruments (diagram if helpful)."],["Variables","Manipulated (what you change), responding (what you measure), controlled (what you keep the same, at least 2)."],["Method","Numbered steps in the present tense; at least 5 different values; repeat readings."],["Results","Table headings with units; the graph you would plot."],["Interpretation","What result would SUPPORT the hypothesis (e.g. graph slopes down)."],["Precautions / limitations","One precaution and one source of error or limitation."]]}],"examples":[{"id":"week15.15.7.e1","title":"Micrometer reading","question":"Read the micrometer shown.","img":{"src":"img/week15/micrometer","alt":"Read the micrometer shown.","w":1094,"h":380},"steps":[{"label":"Sleeve","text":"Last mm mark showing ⟪=4\\,\\mathrm{mm}⟫; a half-mm mark is visible after it → 4.5 mm"},{"label":"Thimble","text":"Line on the datum ⟪=32\\rightarrow 32\\times 0.01=0.32\\,\\mathrm{mm}⟫"},{"label":"Add","text":"⟪4.5+0.32=4.82\\,\\mathrm{mm}⟫"}],"answer":"4.82 mm"},{"id":"week15.15.7.e2","title":"Gradient from a graph","question":"Use Figure 15.2 to find the gradient of the T^2^–l graph and hence g, using ⟪g=4\\pi ^{2}⟫ ÷ gradient.","steps":[{"label":"Triangle","text":"⟪\\Delta y=3.82-1.01=2.81\\,\\mathrm{s}^{2}⟫; ⟪\\Delta x=0.95-0.25=0.70\\,\\mathrm{m}⟫"},{"label":"Gradient","text":"⟪2.81\\div 0.70=4.0\\,\\mathrm{s}^{2}\\,\\mathrm{m}^{-1}⟫"},{"label":"g","text":"⟪g=4\\pi ^{2}\\div 4.0=39.5\\div 4.0=9.9\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫"}],"answer":"Gradient ≈ 4.0 s^2^ m^−1^; ⟪g\\approx 9.9\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫"}]},"tryit":[{"id":"week15.15.7.p1","kind":"self","q":"Read: (i) the vernier calipers in Figure 15.1 is done for you. Now read (ii) the ammeter and (iii) the thermometer below, and (iv) state the smallest division of each.","marks":4,"level":3,"img":{"src":"img/week15/meters","alt":"Read: (i) the vernier calipers in Figure 15.1 is done for you. Now read (ii) the ammeter and (iii) the thermometer below, and (iv) state the smallest division of each.","w":1374,"h":390},"lines":4,"scheme":"(ii) Ammeter: 0.65 A (1) (each small division ⟪=0.05\\,\\mathrm{A}⟫). (iii) Thermometer: 47 °C (1) (each small division ⟪=1\\,{}^{\\circ}\\mathrm{C}⟫). (iv) Ammeter 0.05 A (1); thermometer 1 °C (1).","points":[{"text":"(ii) Ammeter: 0.65 A","marks":1},{"text":"(each small division ⟪=0.05\\,\\mathrm{A}⟫). (iii) Thermometer: 47 °C","marks":1},{"text":"(each small division ⟪=1\\,{}^{\\circ}\\mathrm{C}⟫). (iv) Ammeter 0.05 A","marks":1},{"text":"thermometer 1 °C","marks":1}],"section":"try","hint":{"text":"Look back at Example 1 (Micrometer reading). Start like this: Sleeve: Last mm mark showing ⟪=4\\,\\mathrm{mm}⟫; a half-mm mark is visible after it → 4.5 mm","from":1}},{"id":"week15.15.7.p2","kind":"self","q":"A student times 20 oscillations of a pendulum for five lengths: ⟪l=0.20⟫, 0.40, 0.60, 0.80, 1.00 m; ⟪t=18.0⟫, 25.4, 31.1, 35.9, 40.1 s. Draw a results table with suitable headings and units, including columns for the period T and for T^2^. Complete it.","marks":5,"level":3,"lines":9,"scheme":"Headings with quantity/unit: l / m, t / s, T / s, T^2^ / s^2^ (2: −1 per missing unit). ⟪T=t\\div 20⟫: 0.900, 1.270, 1.555, 1.795, 2.005 s (1) (3 decimal places, as ⟪t\\div 20⟫ gives). T^2^: 0.810, 1.61, 2.42, 3.22, 4.02 s^2^ (1). Consistent decimal places/sig. figs (1).","points":[{"text":"Headings with quantity/unit: l / m, t / s, T / s, T^2^ / s^2^","marks":2},{"text":"⟪T=t\\div 20⟫: 0.900, 1.270, 1.555, 1.795, 2.005 s","marks":1},{"text":"(3 decimal places, as ⟪t\\div 20⟫ gives). T^2^: 0.810, 1.61, 2.42, 3.22, 4.02 s^2^","marks":1},{"text":"Consistent decimal places/sig. figs","marks":1}],"section":"try"}],"practice":[{"id":"week15.15.7.p3","kind":"self","q":"Plot a graph of T^2^ (y-axis) against l (x-axis) using your table from Task 2. Draw the line of best fit, find its gradient, and use ⟪g=4\\pi ^{2}⟫ ÷ gradient to find g.","marks":8,"level":3,"img":{"src":"img/week15/graph_paper","alt":"Plot a graph of T2 (y-axis) against l (x-axis) using your table from Task 2. Draw the line of best fit, find its gradient, and use g = 4π2 ÷ gradient to find g.","w":1174,"h":894},"lines":4,"scheme":"Axes labelled T^2^ / s^2^ and l / m (1); sensible scale using > half the grid (1); 5 points plotted correctly (2, −1 per error); straight line of best fit through the origin (1); large triangle shown (1); gradient ⟪=4.0\\,\\mathrm{s}^{2}\\,\\mathrm{m}^{-1}⟫ (accept 3.9–4.1) (1); ⟪g=4\\pi ^{2}\\div 4.0\\approx 9.9\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫ (accept 9.6–10.1) (1).","points":[{"text":"Axes labelled T^2^ / s^2^ and l / m","marks":1},{"text":"sensible scale using > half the grid","marks":1},{"text":"5 points plotted correctly (2, −1 per error); straight line of best fit through the origin","marks":1},{"text":"large triangle shown","marks":1},{"text":"gradient ⟪=4.0\\,\\mathrm{s}^{2}\\,\\mathrm{m}^{-1}⟫ (accept 3.9–4.1)","marks":1},{"text":"⟪g=4\\pi ^{2}\\div 4.0\\approx 9.9\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫ (accept 9.6–10.1)","marks":1}],"conf":"low","section":"practice","hint":{"text":"Look back at Example 2 (Gradient from a graph). Start like this: Triangle: ⟪\\Delta y=3.82-1.01=2.81\\,\\mathrm{s}^{2}⟫; ⟪\\Delta x=0.95-0.25=0.70\\,\\mathrm{m}⟫","from":2}},{"id":"week15.15.7.p4","kind":"self","q":"State TWO precautions, with reasons, for EACH of: (a) finding the period of a pendulum; (b) measuring the resistance of a wire; (c) finding the specific heat capacity of a metal block electrically.","marks":6,"level":3,"lines":9,"scheme":"(a) Any two (1 each): small amplitude so T is independent of amplitude; time 20 oscillations to reduce effect of reaction time; fiducial mark at centre to count accurately; measure l to the centre of the bob. (b) Any two (1 each): switch off between readings so the wire does not heat/change resistance; check meters read zero; read meters at eye level to avoid parallax; tight connections. (c) Any two (1 each): lag/insulate block to reduce heat loss; put oil in the thermometer hole for good thermal contact; read thermometer at eye level; record the highest temperature reached after switching off.","points":[{"text":"(a) Any two (1 each): small amplitude so T is independent of amplitude; time 20 oscillations to reduce effect of reaction time; fiducial mark at centre to count accurately; measure l to the centre of the bob. (b) Any two (1 each): switch off between readings so the wire does not heat/change resistance; check meters read zero; read meters at eye level to avoid parallax; tight connections. (c) Any two (1 each): lag/insulate block to reduce heat loss; put oil in the thermometer hole for good thermal contact; read thermometer at eye level; record the highest temperature reached after switching off.","marks":6,"each":true}],"section":"practice"}],"exit":[{"id":"week15.15.7.p5","kind":"self","q":"A student times ONE swing of a pendulum with a stopwatch and gets 1.3 s, 1.1 s and 1.4 s. (a) Name the main source of error and its type. (b) State two ways to reduce it. (c) The student measured the length to the TOP of the bob. Name this type of error and say how to correct it.","marks":5,"level":3,"lines":7,"scheme":"(a) Human reaction time in starting/stopping the stopwatch (1); random error (1). (b) Time 20 (or more) oscillations and divide by 20 (1); repeat and average / use a fiducial mark (1). (c) Systematic error: every length is too short by the bob's radius; measure to the centre of the bob (or add the radius to each length) (1).","points":[{"text":"(a) Human reaction time in starting/stopping the stopwatch","marks":1},{"text":"random error","marks":1},{"text":"(b) Time 20 (or more) oscillations and divide by 20","marks":1},{"text":"repeat and average / use a fiducial mark","marks":1},{"text":"(c) Systematic error: every length is too short by the bob's radius; measure to the centre of the bob (or add the radius to each length)","marks":1}],"section":"exit"},{"id":"week15.15.7.p6","kind":"self","q":"Plan and design an experiment to test this hypothesis: 'The thicker the insulation around a can of hot water, the slower the water cools.' Include: aim, apparatus, variables, method, expected results and one precaution.","marks":10,"level":3,"lines":16,"scheme":"Aim: to investigate how the thickness (number of layers) of insulation affects the rate of cooling of hot water (1). Apparatus: identical metal cans, insulation (e.g. cotton wool/felt) in layers, thermometer, stopwatch, measuring cylinder, kettle (2: any 4 items). Manipulated: thickness/number of layers of insulation (1). Responding: temperature fall in a fixed time, e.g. 10 min (1). Controlled (any two): same volume of water, same starting temperature, same can, same room/no draughts, lid on (1). Method: wrap can with 1 layer, add fixed volume of hot water, record starting temperature, record temperature after 10 min; repeat with 2, 3, 4, 5 layers (and no insulation) (2). Expected result: the temperature drop decreases as thickness increases (graph of temperature fall against layers slopes down) supports the hypothesis (1). Precaution: stir before reading / read thermometer at eye level / same starting temperature (1).","points":[{"text":"Aim: to investigate how the thickness (number of layers) of insulation affects the rate of cooling of hot water","marks":1},{"text":"Apparatus: identical metal cans, insulation (e.g. cotton wool/felt) in layers, thermometer, stopwatch, measuring cylinder, kettle","marks":2},{"text":"Manipulated: thickness/number of layers of insulation","marks":1},{"text":"Responding: temperature fall in a fixed time, e.g. 10 min","marks":1},{"text":"Controlled (any two): same volume of water, same starting temperature, same can, same room/no draughts, lid on","marks":1},{"text":"Method: wrap can with 1 layer, add fixed volume of hot water, record starting temperature, record temperature after 10 min; repeat with 2, 3, 4, 5 layers (and no insulation)","marks":2},{"text":"Expected result: the temperature drop decreases as thickness increases (graph of temperature fall against layers slopes down) supports the hypothesis","marks":1},{"text":"Precaution: stir before reading / read thermometer at eye level / same starting temperature","marks":1}],"section":"exit"}],"warmup":[{"id":"week15.15.7.w1","kind":"mcq","q":"The speed of a car on a highway is most likely to be","marks":1,"level":1,"options":["0.25 m s^−1^","25 m s^−1^","250 m s^−1^","2500 m s^−1^"],"answer":"B","explanation":"(1). ⟪25\\,\\mathrm{m}\\,\\mathrm{s}^{-1}=90\\,\\mathrm{km}\\,\\mathrm{h}^{-1}⟫. 250 m s^−1^ is a jet airliner. **Technique: sense check / estimating.**","section":"warmup","src":"week15.15.6.p6"},{"id":"week15.15.7.w2","kind":"mcq","q":"Which of the following increase the pressure at the bottom of a tank of liquid? I Increasing the depth of liquid  II Using a denser liquid  III Using a wider tank","marks":1,"level":1,"options":["I only","I and II only","II and III only","I, II and III"],"answer":"B","explanation":"(1). ⟪P=\\rho gh⟫: depth ✓ (I), density ✓ (II); width does not appear in the formula ✗ (III). **Technique: true/false each statement.**","section":"warmup","src":"week15.15.6.p5"},{"id":"week15.15.7.w3","kind":"mcq","q":"A graph of y against x is a straight line through the origin. This shows that","marks":1,"level":1,"options":["y is directly proportional to x","y is constant","y is inversely proportional to x","y decreases as x increases"],"answer":"A","explanation":"(1). Straight line + through the origin = direct proportion. **Technique: reading graphs fast.**","section":"warmup","src":"week15.15.6.p3"}],"n":118},{"id":"week15.check","kind":"check","title":"Book check","titleText":"Book check","check":true,"watchOut":["Leaving answers blank in Paper 01. There is NO penalty for wrong answers: always shade something.","Not reading NOT / EXCEPT / LEAST in the question. Underline these words before you look at the options.","Using minutes instead of seconds (Q = It, ⟪P=E\\div t⟫). Change to seconds first; for kWh, use hours.","Using °C instead of kelvin in gas-law calculations. Add 273 first.","Forgetting to square: v in ⟪E_{k}=\\tfrac{1}{2}mv^{2}⟫, c in ⟪E=mc^{2}⟫, I in ⟪P=I^{2}R⟫.","Echo questions: forgetting the sound travels there AND back (divide the total distance by 2).","Amplitude measured crest to trough instead of centre line to crest.","Parallel resistance: giving 1/R instead of R, or a total bigger than the smallest resistor.","Graphs: units next to every number in a table instead of in the heading; scales of 3 or 7 per square; joining points dot to dot.","Shading errors after skipping a question. Check the row number every 10 questions."],"mcq":[{"id":"week15.check.m1","kind":"mcq","q":"The diameter of a thin wire is recorded as 0.52 mm. The most suitable instrument for this measurement is a","marks":1,"level":1,"options":["metre rule","vernier calipers","measuring tape","micrometer screw gauge"],"answer":"D","explanation":"0.52 mm needs precision to 0.01 mm: only the micrometer reads that finely. Vernier calipers (B) read to 0.1 mm.","section":"p01"},{"id":"week15.check.m2","kind":"mcq","q":"How many significant figures are there in 0.04060?","marks":1,"level":1,"options":["2","3","5","4"],"answer":"D","explanation":"Leading zeros do not count; the digits 4, 0, 6, 0 do (the zero between 4 and 6 and the final zero both count). 3 forgets the final zero.","section":"p01"},{"id":"week15.check.m3","kind":"mcq","q":"Which of the following is an example of a SYSTEMATIC error?","marks":1,"level":1,"options":["a student's reaction time varies when using a stopwatch","a draught makes a pendulum swing unevenly","a reading is sometimes taken from above and sometimes from below","a balance reads 0.2 g when nothing is on it"],"answer":"D","explanation":"A zero error adds the same amount to every reading: systematic. A, B and C vary randomly from reading to reading.","section":"p01"},{"id":"week15.check.m4","kind":"mcq","q":"Use the velocity–time graph. The acceleration of the car during the first 4 s is","marks":1,"level":1,"img":{"src":"img/week15/vt","alt":"Use the velocity–time graph. The acceleration of the car during the first 4 s is","w":932,"h":574},"options":["4 m s^−2^","80 m s^−2^","5 m s^−2^","0.2 m s^−2^"],"answer":"C","explanation":"Gradient ⟪=20\\div 4=5\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫. D is ⟪4\\div 20⟫ (upside down); B multiplies.","section":"p01"},{"id":"week15.check.m5","kind":"mcq","q":"A book rests on a table. According to Newton's third law, the force paired with the Earth's pull on the book is","marks":1,"level":1,"options":["the table pushing up on the book","the book pulling up on the Earth","the book pushing down on the table","the Earth pulling down on the table"],"answer":"B","explanation":"Third-law pairs act on DIFFERENT bodies and are the same type of force: Earth pulls book (gravity) ↔ book pulls Earth (gravity). A is equal and opposite but acts on the same body, so it is not the pair.","section":"p01"},{"id":"week15.check.m6","kind":"mcq","q":"A force of 40 N is applied at right angles to a spanner, 0.25 m from the centre of the nut. The moment is","marks":1,"level":1,"options":["160 N m","10 N m","0.0063 N m","40 N m"],"answer":"B","explanation":"Moment ⟪=F\\times d=40\\times 0.25=10\\,\\mathrm{N}\\,\\mathrm{m}⟫. A divides 40 by 0.25.","section":"p01"},{"id":"week15.check.m7","kind":"mcq","q":"A car of mass 1200 kg travels at 20 m s^−1^. Its kinetic energy is","marks":1,"level":1,"options":["⟪2.4\\times 10^{5}\\,\\mathrm{J}⟫","⟪1.2\\times 10^{4}\\,\\mathrm{J}⟫","⟪2.4\\times 10^{4}\\,\\mathrm{J}⟫","⟪4.8\\times 10^{5}\\,\\mathrm{J}⟫"],"answer":"A","explanation":"⟪E_{k}=\\tfrac{1}{2}mv^{2}=0.5\\times 1200\\times 400=240\\,000\\,\\mathrm{J}=2.4\\times 10^{5}\\,\\mathrm{J}⟫. B forgets to square v; C forgets both the square and the ½; D forgets the ½.","section":"p01"},{"id":"week15.check.m8","kind":"mcq","q":"A block of wood floats at rest in water. The upthrust on the block is","marks":1,"level":1,"options":["equal to its weight","greater than its weight","less than its weight","zero"],"answer":"A","explanation":"At rest, the forces balance: upthrust = weight = weight of water displaced (Archimedes).","section":"p01"},{"id":"week15.check.m9","kind":"mcq","q":"Which of the following energy sources used in the Caribbean is renewable?","marks":1,"level":1,"options":["geothermal","coal","natural gas","diesel"],"answer":"A","explanation":"Geothermal energy (e.g. in volcanic islands) is renewable. Coal, gas and diesel are fossil fuels and will run out.","section":"p01"},{"id":"week15.check.m10","kind":"mcq","q":"When the temperature of a gas rises, its molecules","marks":1,"level":1,"options":["get bigger","move faster on average","move closer together","stop colliding"],"answer":"B","explanation":"Temperature is linked to the average kinetic energy of the molecules, so they move faster. Molecules do not change size (A).","section":"p01"},{"id":"week15.check.m11","kind":"mcq","q":"The unit of specific heat capacity is","marks":1,"level":1,"options":["J K^−1^","J kg^−1^","J kg K^−1^","J kg^−1^ K^−1^"],"answer":"D","explanation":"⟪c=E\\div (m\\Delta \\theta )\\rightarrow J\\div (\\mathrm{kg}\\times K)⟫. A is heat capacity; B is specific latent heat.","section":"p01"},{"id":"week15.check.m12","kind":"mcq","q":"Which thermometer is best for measuring the rapidly changing temperature inside a furnace at 1000 °C?","marks":1,"level":1,"options":["clinical thermometer","thermocouple","mercury-in-glass thermometer","alcohol-in-glass thermometer"],"answer":"B","explanation":"A thermocouple has a very wide range and responds quickly. Mercury boils at 357 °C and glass would melt.","section":"p01"},{"id":"week15.check.m13","kind":"mcq","q":"Ponds in cold countries freeze from the top down because","marks":1,"level":1,"options":["ice is denser than water","heat rises by conduction","water is densest at 4 °C, so the coldest water stays at the top","the bottom of the pond is heated by the Sun"],"answer":"C","explanation":"Water is densest at 4 °C, so 4 °C water sinks and colder water (and ice) stays on top. Ice is LESS dense than water (A is wrong).","section":"p01"},{"id":"week15.check.m14","kind":"mcq","q":"In a vacuum flask, the silvered surfaces mainly reduce heat transfer by","marks":1,"level":1,"options":["conduction","radiation","convection","evaporation"],"answer":"B","explanation":"Shiny surfaces are poor emitters and good reflectors of infrared. The vacuum stops conduction and convection.","section":"p01"},{"id":"week15.check.m15","kind":"mcq","q":"A wave has a frequency of 25 Hz. Its period is","marks":1,"level":1,"options":["0.04 s","0.4 s","25 s","40 s"],"answer":"A","explanation":"⟪T=1\\div f=1\\div 25=0.04\\,\\mathrm{s}⟫.","section":"p01"},{"id":"week15.check.m16","kind":"mcq","q":"Ultrasound is used for scanning a baby in the womb because it","marks":1,"level":1,"options":["is an electromagnetic wave","is reflected at boundaries between tissues and is safe","has a frequency below 20 Hz","travels faster than light"],"answer":"B","explanation":"Ultrasound (above 20 kHz) is sound, not EM (A); it reflects at tissue boundaries and does not ionise, so it is safe.","section":"p01"},{"id":"week15.check.m17","kind":"mcq","q":"Which list is in order of INCREASING frequency?","marks":1,"level":1,"options":["visible, infrared, microwave, radio","radio, microwave, infrared, visible","gamma, X-ray, ultraviolet, visible","infrared, radio, visible, microwave"],"answer":"B","explanation":"Radio has the lowest frequency; frequency increases towards gamma. A and C are in DEcreasing order.","section":"p01"},{"id":"week15.check.m18","kind":"mcq","q":"The image formed by a pinhole camera is","marks":1,"level":1,"options":["real and inverted","virtual and upright","virtual and inverted","real and upright"],"answer":"A","explanation":"Light travels in straight lines through the hole, so rays cross and the image is inverted; it forms on a screen, so it is real.","section":"p01"},{"id":"week15.check.m19","kind":"mcq","q":"Optical fibres carry light signals by","marks":1,"level":1,"options":["total internal reflection","refraction only","diffraction","dispersion"],"answer":"A","explanation":"Light hits the fibre wall at more than the critical angle and is totally internally reflected along the fibre.","section":"p01"},{"id":"week15.check.m20","kind":"mcq","q":"A converging lens forms an image 6.0 cm tall of an object 2.0 cm tall. The image is 30 cm from the lens. The object distance is","marks":1,"level":1,"options":["10 cm","15 cm","60 cm","90 cm"],"answer":"A","explanation":"⟪m=6.0\\div 2.0=3⟫; ⟪m=v\\div u⟫, so ⟪u=30\\div 3=10\\,\\mathrm{cm}⟫. D multiplies instead of dividing.","section":"p01"},{"id":"week15.check.m21","kind":"mcq","q":"The direction of an electric field line is","marks":1,"level":1,"options":["from negative to positive","from north to south","at right angles to the force on a charge","from positive to negative"],"answer":"D","explanation":"Field direction = direction of the force on a POSITIVE charge, so lines go from + to −. B describes magnetic fields.","section":"p01"},{"id":"week15.check.m22","kind":"mcq","q":"A voltmeter should have","marks":1,"level":1,"options":["a low resistance and be connected in series","a low resistance and be connected in parallel","a high resistance and be connected in series","a high resistance and be connected in parallel"],"answer":"D","explanation":"A voltmeter is connected across (in parallel with) the component and must take almost no current, so it has very high resistance. A describes an ammeter.","section":"p01"},{"id":"week15.check.m23","kind":"mcq","q":"As the current through a filament lamp increases, its I–V graph curves because","marks":1,"level":1,"options":["the lamp obeys Ohm's law","its resistance decreases as it gets hotter","its resistance increases as it gets hotter","the voltage stays constant"],"answer":"C","explanation":"The hot filament has higher resistance, so the current rises less and less for each extra volt. An ohmic conductor (A) gives a straight line.","section":"p01"},{"id":"week15.check.m24","kind":"mcq","q":"24 J of energy is transferred when 4.0 C of charge passes through a lamp. The potential difference across the lamp is","marks":1,"level":1,"options":["96 V","0.17 V","6.0 V","28 V"],"answer":"C","explanation":"⟪V=E\\div Q=24\\div 4.0=6.0\\,\\mathrm{V}⟫. A multiplies; B divides the wrong way.","section":"p01"},{"id":"week15.check.m25","kind":"mcq","q":"The earth wire in a plug protects the user by","marks":1,"level":1,"options":["carrying current to earth if a live wire touches the metal case","stopping the fuse from melting","reducing the voltage of the supply","keeping the appliance switched on"],"answer":"A","explanation":"If the live wire touches the metal case, a large current flows to earth, blowing the fuse and making the case safe to touch.","section":"p01"},{"id":"week15.check.m26","kind":"mcq","q":"The size of the emf induced when a magnet is pushed into a coil is increased by","marks":1,"level":1,"options":["pushing the magnet in more slowly","using a coil with fewer turns","pushing the magnet in faster","holding the magnet still inside the coil"],"answer":"C","explanation":"Faraday: emf depends on the RATE of change of flux. Faster motion, more turns or a stronger magnet increase it. Holding still gives zero emf (D).","section":"p01"},{"id":"week15.check.m27","kind":"mcq","q":"The right-hand grip rule is used to find the direction of the","marks":1,"level":1,"options":["force on a wire in a magnetic field","induced current in a generator","magnetic field around a current-carrying wire or solenoid","electron flow in a circuit"],"answer":"C","explanation":"Thumb along the current, fingers curl in the direction of the field. A uses Fleming's LEFT-hand rule; B uses the RIGHT-hand (dynamo) rule.","section":"p01"},{"id":"week15.check.m28","kind":"mcq","q":"Compared with a proton, an electron has","marks":1,"level":1,"options":["the same mass and opposite charge","about 1/1840 of the mass and the same charge","the same mass and no charge","about 1/1840 of the mass and opposite charge"],"answer":"D","explanation":"Electron: charge −1, mass ≈ 1/1840 of a proton. C describes a neutron (roughly).","section":"p01"},{"id":"week15.check.m29","kind":"mcq","q":"Gamma rays are NOT deflected by electric or magnetic fields because they","marks":1,"level":1,"options":["travel too fast","are very heavy","have no charge","have a short range"],"answer":"C","explanation":"Only charged particles are deflected. Gamma is an uncharged EM wave.","section":"p01"},{"id":"week15.check.m30","kind":"mcq","q":"Carbon-14 has a half-life of 5730 years. A piece of wood has one quarter of the carbon-14 of living wood. Its age is about","marks":1,"level":1,"options":["2865 years","11 460 years","5730 years","22 920 years"],"answer":"B","explanation":"1 → ½ → ¼ is TWO half-lives: ⟪2\\times 5730=11\\,460\\,\\mathrm{years}⟫. C is only one half-life.","section":"p01"}],"structured":[],"n":119},{"id":"week15.past","kind":"past","title":"Past-paper practice","titleText":"Past-paper practice","check":true,"log":true,"questions":[{"id":"week15.past.q1","kind":"multi","title":"Practical data analysis (Paper 032 / Paper 02 Q1 style): resistance of a wire","total":20,"stem":["A student investigates how the resistance, R, of a nichrome wire depends on its length, l. She connects different lengths of the wire in a circuit with a cell, an ammeter, a voltmeter, a rheostat and a switch. She adjusts the rheostat so that the current is 0.50 A each time and reads the voltage, V."],"stemBlocks":[{"type":"table","headers":["l / m","0.20","0.40","0.60","0.80","1.00"],"rows":[["V / V","0.42","0.80","1.26","1.62","2.05"],["I / A","0.50","0.50","0.50","0.50","0.50"],["R / Ω","0.84","","2.52","","4.10"]]}],"parts":[{"id":"week15.past.q1.a","kind":"self","q":"Draw a circuit diagram of the arrangement she used.","marks":3,"level":2,"lines":7,"scheme":"Ammeter in series with the wire (1); voltmeter in parallel across the wire only (1); cell, rheostat and switch in series, correct symbols (1).","points":[{"text":"Ammeter in series with the wire","marks":1},{"text":"voltmeter in parallel across the wire only","marks":1},{"text":"cell, rheostat and switch in series, correct symbols","marks":1}],"label":"(a)"},{"id":"week15.past.q1.b","kind":"self","q":"Complete the table by calculating R for ⟪l=0.40\\,\\mathrm{m}⟫ and ⟪l=0.80\\,\\mathrm{m}⟫.","marks":2,"level":2,"lines":2,"scheme":"⟪R=V\\div I=0.80\\div 0.50=1.60\\,\\Omega⟫ (1); ⟪1.62\\div 0.50=3.24\\,\\Omega⟫ (1).","points":[{"text":"⟪R=V\\div I=0.80\\div 0.50=1.60\\,\\Omega⟫","marks":1},{"text":"⟪1.62\\div 0.50=3.24\\,\\Omega⟫","marks":1}],"label":"(b)"},{"id":"week15.past.q1.c","kind":"self","q":"Plot a graph of R (y-axis) against l (x-axis). Draw the line of best fit.","marks":6,"level":3,"img":{"src":"img/week15/graph_paper","alt":"Plot a graph of R (y-axis) against l (x-axis). Draw the line of best fit.","w":1174,"h":894},"lines":0,"scheme":"Axes labelled R / Ω and l / m (1); sensible scale using > half the grid (1); all 5 points correct (2, −1 per error); straight best-fit line through (or very near) the origin (1); title or neat thin line (1).","points":[{"text":"Axes labelled R / Ω and l / m","marks":1},{"text":"sensible scale using > half the grid","marks":1},{"text":"all 5 points correct (2, −1 per error); straight best-fit line through (or very near) the origin","marks":1},{"text":"title or neat thin line","marks":1}],"conf":"low","label":"(c)","grid":true},{"id":"week15.past.q1.d","kind":"self","q":"Determine the gradient of the graph. Show your triangle and give the unit.","marks":3,"level":2,"lines":3,"scheme":"Large triangle shown on the line (1); gradient ≈ 4.1 (accept 4.0–4.2) (1); unit Ω m^−1^ (1).","points":[{"text":"Large triangle shown on the line","marks":1},{"text":"gradient ≈ 4.1 (accept 4.0–4.2)","marks":1},{"text":"unit Ω m^−1^","marks":1}],"label":"(d)"},{"id":"week15.past.q1.e","kind":"self","q":"Use your graph to find the resistance of 0.65 m of this wire.","marks":2,"level":2,"lines":2,"scheme":"Reading shown on graph at ⟪l=0.65\\,\\mathrm{m}⟫ (1); ⟪R\\approx 2.7\\,\\Omega⟫ (accept 2.6–2.8 Ω) (1).","points":[{"text":"Reading shown on graph at ⟪l=0.65\\,\\mathrm{m}⟫","marks":1},{"text":"⟪R\\approx 2.7\\,\\Omega⟫ (accept 2.6–2.8 Ω)","marks":1}],"num":{"value":2.7,"sf":2,"unit":"Ω","unitTex":"\\Omega","min":2.6,"max":2.8},"label":"(e)","autoKind":"num"},{"id":"week15.past.q1.f","kind":"self","q":"State TWO precautions she should take to obtain accurate results.","marks":2,"level":2,"lines":3,"scheme":"Any two (1 each): switch off between readings so the wire does not heat up; read the meters at eye level/perpendicular to avoid parallax; check meters read zero before starting; measure l between the contact points with the wire straight; tight clean connections.","points":[{"text":"Any two (1 each): switch off between readings so the wire does not heat up; read the meters at eye level/perpendicular to avoid parallax; check meters read zero before starting; measure l between the contact points with the wire straight; tight clean connections.","marks":2,"each":true}],"label":"(f)"},{"id":"week15.past.q1.g","kind":"self","q":"State what the graph shows about the relationship between R and l, and give ONE source of error.","marks":2,"level":2,"lines":3,"scheme":"R is directly proportional to l (straight line through the origin) (1). Error (any one) (1): heating of the wire changes R; contact resistance at the crocodile clips; parallax in reading the metre rule/meters; wire not uniform.","points":[{"text":"R is directly proportional to l (straight line through the origin)","marks":1},{"text":"Error (any one). : heating of the wire changes R; contact resistance at the crocodile clips; parallax in reading the metre rule/meters; wire not uniform","marks":1}],"label":"(g)"}]},{"id":"week15.past.q2","kind":"multi","title":"Planning and design (Paper 032 style)","total":12,"stem":["A student notices that a marble rolls down a steep ramp faster than down a gentle one. She makes this hypothesis: 'The greater the angle of the ramp, the shorter the time the marble takes to roll down it.'"],"stemBlocks":[],"parts":[{"id":"week15.past.q2.a","kind":"self","q":"State the aim of an experiment to test this hypothesis.","marks":1,"level":1,"lines":2,"scheme":"To investigate how the angle of a ramp affects the time taken for a marble to roll down it (1).","points":[{"text":"To investigate how the angle of a ramp affects the time taken for a marble to roll down it","marks":1}],"label":"(a)"},{"id":"week15.past.q2.b","kind":"self","q":"List the apparatus needed.","marks":2,"level":2,"lines":2,"scheme":"Any four (2; 1 for two or three): ramp/plank, marble, protractor (or metre rule to set height), stopwatch, blocks/stand to support the ramp, metre rule.","points":[{"text":"Any four. : ramp/plank, marble, protractor (or metre rule to set height), stopwatch, blocks/stand to support the ramp, metre rule","marks":2}],"label":"(b)"},{"id":"week15.past.q2.c","kind":"self","q":"Identify the manipulated, responding and TWO controlled variables.","marks":3,"level":2,"lines":4,"scheme":"Manipulated: angle of the ramp (1). Responding: time to roll down (1). Controlled, any two: same marble, same length of ramp, same surface, released from rest from the same point (1).","points":[{"text":"Manipulated: angle of the ramp","marks":1},{"text":"Responding: time to roll down","marks":1},{"text":"Controlled, any two: same marble, same length of ramp, same surface, released from rest from the same point","marks":1}],"label":"(c)"},{"id":"week15.past.q2.d","kind":"self","q":"Describe the method you would use.","marks":4,"level":3,"lines":8,"scheme":"Set ramp at 10° measured with the protractor (1); release the marble from rest at the top mark and time it to the bottom (1); repeat 3 times and average (1); repeat for at least five angles, e.g. 10°, 15°, 20°, 25°, 30° (1).","points":[{"text":"Set ramp at 10° measured with the protractor","marks":1},{"text":"release the marble from rest at the top mark and time it to the bottom","marks":1},{"text":"repeat 3 times and average","marks":1},{"text":"repeat for at least five angles, e.g. 10°, 15°, 20°, 25°, 30°","marks":1}],"label":"(d)"},{"id":"week15.past.q2.e","kind":"self","q":"State the result that would support the hypothesis, and ONE limitation of the experiment.","marks":2,"level":2,"lines":3,"scheme":"The average time decreases as the angle increases (1). Limitation (any one) (1): reaction time is large compared with short times at steep angles; marble may slip or roll off line; friction/air resistance.","points":[{"text":"The average time decreases as the angle increases","marks":1},{"text":"Limitation (any one). : reaction time is large compared with short times at steep angles; marble may slip or roll off line; friction/air resistance","marks":1}],"label":"(e)"}]}],"n":120}]};
